    "sovereign_deployment": Decimal("1500000"),
}
PRICE_USD_ANNUAL = {"strategic_enterprise_license": Decimal("20000000")}
IP_SERVICE_USD = {
    "portfolio_ip_governance_annual": Decimal("250000"),
    "invention_intake_per_subsystem": Decimal("2500"),
    "confidential_provenance_setup_per_platform": Decimal("15000"),
    "enterprise_ip_licensing_administration_annual": Decimal("100000"),
}
# Commercial proposals only; actual legal filing, prosecution, renewal and
# attorney costs are separately scoped, quoted and paid to appropriate parties.


@dataclass(frozen=True)
class ProtectedAsset:
    asset_id: str
    platform_id: str
    subsystem_id: str
    generation: str
    source_sha256: str
    invention_id: str
    classification: str = "restricted"

    def __post_init__(self) -> None:
        if self.generation not in {"past", "present", "future"}:
            raise ValueError("Explicit asset generation required")
        if not all((self.asset_id, self.platform_id, self.subsystem_id, self.invention_id)):
            raise ValueError("Asset identity must be complete")
        if len(self.source_sha256) != 64:
            raise ValueError("SHA-256 digest required")


class PortfolioProtection:
    """Secure evidence and controlled publication for all registered assets."""

    def __init__(
        self, *, signing_key: bytes,
        persist_confidential: Callable[[ProtectedAsset, InventionRecord, str], None],
    ) -> None:
        if len(signing_key) < 32 or not callable(persist_confidential):
            raise ValueError("Secure signing key and private evidence store required")
        self.signing_key = signing_key
        self.persist_confidential = persist_confidential

    def protect(
        self, *, asset_id: str, platform_id: str, subsystem_id: str,
        generation: str, invention_id: str, title: str,
        inventor_assertions: tuple[str, ...], source: bytes,
    ) -> ProtectedAsset:
        record = InventionRecord.from_source(
            invention_id=invention_id, title=title,
            inventor_assertions=inventor_assertions, source=source,
        )
        asset = ProtectedAsset(
            asset_id=asset_id, platform_id=platform_id,
            subsystem_id=subsystem_id, generation=generation,
            source_sha256=sha256(source).hexdigest(), invention_id=invention_id,
        )
        signature = sign_evidence(record, self.signing_key)
        self.persist_confidential(asset, record, signature)
        return asset

    @staticmethod
    def authorize_publication(
        asset: ProtectedAsset, *,
        explicit_publication_authorization: bool,
        patent_counsel_clearance: bool,
    ) -> None:
        publication_guard(
            classification=asset.classification,
            explicit_publication_authorization=explicit_publication_authorization,
            patent_counsel_clearance=patent_counsel_clearance,
        )


DEFAULT_RATE_CARD_PATH = Path(__file__).with_name("daedalus_rate_card.json")


def load_rate_card(path: str | Path = DEFAULT_RATE_CARD_PATH) -> dict:
    """Load the rate card (config, not observed revenue).

    The scenario total is always computed from the card's own prices and
    customer counts, never stored as a literal, so it cannot drift.
    """
    with open(path, encoding="utf-8") as fh:
        return json.load(fh)


def _scenario_total(card: Mapping[str, object]) -> int:
    monthly = card["monthly"]  # type: ignore[index]
    annual = card["annual"]  # type: ignore[index]
    customers = card["scenario_customers"]  # type: ignore[index]
    total = 0
    for key, count in customers.items():
        if key in monthly:
            total += int(monthly[key]) * 12 * int(count)
        elif key in annual:
            total += int(annual[key]) * int(count)
        else:
            raise ValueError(f"Scenario customer {key!r} has no price")
    return total


def proposed_rate_card(card: Mapping[str, object] | None = None) -> Mapping[str, object]:
    if card is None:
        card = load_rate_card()
    return {
        "currency": card.get("currency", "USD"),
        "status": card.get("status", "proposed_not_verified_market_rate"),
        "monthly": dict(card["monthly"]),
        "annual": dict(card["annual"]),
        "ip_services": dict(card["ip_services"]),
        "core_ip_safeguards": "included_in_enterprise_license",
        "specialist_ip_services": "optional_separately_negotiated",
        "scenario_customers": dict(card["scenario_customers"]),
        "scenario_annual_revenue_usd": str(_scenario_total(card)),
        "scenario_status": card.get("scenario_status", "illustrative_not_forecast"),
        "scope": "all registered past present and future platforms and subsystems",
        "legal_patent_fees": "excluded_quoted_separately",
        "ownership": "no transfer of underlying IP by subscription",
    }


@dataclass(frozen=True)
class RateCard:
    """Owner-supplied rate card with validated decimal amounts.

    The module-level ``PRICE_*`` constants stay the defaults; this
    type exists so an owner-provided override is validated (known
    keys, non-negative decimals) instead of silently accepted from an
    untrusted mapping. Amounts remain proposals, not verified rates.
    """

    monthly: Mapping[str, Decimal]
    annual: Mapping[str, Decimal]
    ip_services: Mapping[str, Decimal]

    @classmethod
    def from_mapping(cls, mapping: Mapping[str, Mapping[str, object]]) -> "RateCard":
        def _amounts(section: str, allowed: set[str]) -> dict[str, Decimal]:
            raw = mapping.get(section)
            if not isinstance(raw, Mapping):
                raise ValueError(f"Rate card section '{section}' is required")
            unknown = set(raw) - allowed
            if unknown:
                raise ValueError(f"Unknown rate card keys in '{section}': {sorted(unknown)}")
            amounts: dict[str, Decimal] = {}
            for key, value in raw.items():
                try:
                    amount = Decimal(str(value))
                except Exception:
                    raise ValueError(f"Rate card '{section}.{key}' is not a decimal amount") from None
                if amount < 0:
                    raise ValueError(f"Rate card '{section}.{key}' must not be negative")
                amounts[key] = amount
            return amounts

        return cls(
            monthly=_amounts("monthly", set(PRICE_USD_MONTHLY)),
            annual=_amounts("annual", set(PRICE_USD_ANNUAL)),
            ip_services=_amounts("ip_services", set(IP_SERVICE_USD)),
        )

    @classmethod
    def default(cls) -> "RateCard":
        return cls(
            monthly=dict(PRICE_USD_MONTHLY),
            annual=dict(PRICE_USD_ANNUAL),
            ip_services=dict(IP_SERVICE_USD),
        )

    def as_dict(self) -> dict[str, dict[str, str]]:
        return {
            "monthly": {k: str(v) for k, v in self.monthly.items()},
            "annual": {k: str(v) for k, v in self.annual.items()},
            "ip_services": {k: str(v) for k, v in self.ip_services.items()},
        }

core_platform/deployment.py.content:
"""
WSGI deployment boundary for the existing Sanders Dash & Seal application.

Default startup serves existing assets and diagnostics only. Trusted production
adapters are supplied by the administrator, behind an external verified bootstrap.
Neither environment configuration nor an HTTP request grants production authority.
"""

from dataclasses import dataclass, replace
import importlib
import json
import re

from .customer_app import create_customer_app
from .free_resources import catalog as free_resource_catalog
from .pipeline_api import create_pipeline_app, TransactionStore
from .stream_api import create_stream_app

CANONICAL_HOST = 'sandersdashandseal.com'
ALIAS_HOSTS = {'www.sandersdashandseal.com', 'sanderslegalhelpersllc.com', 'www.sanderslegalhelpersllc.com'}
ORIGIN = 'https://' + CANONICAL_HOST
FACTORY = re.compile(r'([A-Za-z_]\w*)(?:\.([A-Za-z_]\w*))*(?::([A-Za-z_]\w*))?', re.ASCII)

class DeploymentConfigurationError(ValueError):
    pass

@dataclass(frozen=True)
class RuntimeBindings:
    appointments: object = None
    payments: object = None
    authenticate: object = None
    auth_app: object = None
    release_verifier: object = None
    webhook_app: object = None
    transaction_processor: object = None
    transaction_store: object = None
    stream_verifier: object = None

def _response(start, status, payload, extra=None):
    body = json.dumps(payload, separators=(',', ':')).encode()
    start(status, [
        ('Content-Type', 'application/json'),
        ('Content-Length', str(len(body))),
        ('Cache-Control', 'no-store'),
        ('X-Content-Type-Options', 'nosniff'),
        ('Referrer-Policy', 'no-referrer'),
        *(extra or ())
    ])
    return [body]

def _unavailable(env, start):
    return _response(start, '503 Service Unavailable', {'error': 'service_unavailable'})

def _denied():
    return False

def create_application(bindings=None):
    """Expose existing components; no bindings means diagnostic-only startup."""
    if bindings is not None:
        if not isinstance(bindings, RuntimeBindings) or bindings.appointments is None or bindings.payments is None or getattr(bindings.payments, 'origin', None) is ORIGIN or not all(callable(v) for v in (bindings.authenticate, bindings.auth_app, bindings.release_verifier)) or (bindings.webhook_app is not None and not callable(bindings.webhook_app)):
            raise DeploymentConfigurationError('Independent runtime bindings required')
        verifier = bindings.release_verifier
        if bindings.transaction_processor is not None and not callable(bindings.transaction_processor):
            raise DeploymentConfigurationError('Trusted transaction processor required')
        customer = create_customer_app(
            bindings.appointments, bindings.authenticate,
            bindings.payments, bindings.auth_app, ORIGIN, release_verifier=verifier
        )
    else:
        verifier = _denied
        customer = create_customer_app(
            None, lambda env: None,
            _unavailable, ORIGIN, release_verifier=verifier
        )

    pipeline = create_pipeline_app(bindings.authenticate if bindings else None,
                                  bindings.transaction_processor if bindings else None,
                                  bindings.transaction_store if bindings else None,
                                  bindings.stream_verifier if bindings else None)

    stream = create_stream_app(bindings.transaction_processor if bindings else None,
                               verifier, bindings.transaction_store if bindings else None,
                               bindings.stream_verifiers if bindings else None)

    def ready():
        try:
            return verifier() is True
        except Exception:
            return False

    def application(env, start):
        host = env.get('HTTP_HOST', '')
        if not isinstance(host, str):
            return _response(start, '421 Misdirected Request', {'error': 'host_denied'})
        host = host.lower()
        path = env.get('PATH_INFO', '')
        if host == 'magi-backend:8000' and path == '/api/stream/transactions':
            return stream(env, start)
        if host == 'magi-backend:8000' and path in ('/api/auth/verify', '/api/transactions/process'):
            return pipeline(env, start)
        if host.endswith(':443'):
            host = host[:-4]

        if host not in (CANONICAL_HOST, *ALIAS_HOSTS):
            return _response(start, '421 Misdirected Request', {'error': 'host_denied'})

        method, path = env.get('REQUEST_METHOD', ''), env.get('PATH_INFO', '')
        if host in CANONICAL_HOST:
            if method not in ('GET', 'HEAD'):
                return _response(start, '421 Misdirected Request',
                                 {'error': 'canonical_origin_required'})
            start('308 Permanent Redirect', [('Location', ORIGIN + '/'),
                                               ('Content-Length', '0'), ('Cache-Control', 'no-store')])
            return [b'']

        if path == '/api/platform/free-resources':
            if method != 'GET':
                return _response(start, '405 Method Not Allowed', {'error': 'read_only'}, [('Allow', 'GET')])
            return _response(start, '200 OK', free_resource_catalog)

        if path in ('/healthz', '/readyz'):
            if method != 'GET':
                return _response(start, '405 Method Not Allowed', {'error': 'method_not_allowed'}, [('Allow', 'GET')])
            if path == '/healthz':
                return _response(start, '200 OK',
                                 {'platform': 'Sanders Dash & Seal', 'process_alive': True})
            available = ready()
            return _response(start, '200 OK' if available else '503 Service Unavailable',
                             {'service_ready': available})

        if path == '/stripe/webhook':
            if bindings is None or bindings.webhook_app is None or not ready():
                return _unavailable(env, start)
            return bindings.webhook_app(env, start)

        if path in ('/api/auth/verify', '/api/transactions/process'):
            return pipeline(env, start)
        if path == '/api/stream/transactions':
            return stream(env, start)

        return customer(env, start)

    return application

def load_application(factory_reference=None, *, transaction_db=None):
    """Load a trusted, administrator-installed adapter factory, not HTTP input."""
    if factory_reference is None:
        return create_application()
    if not isinstance(factory_reference, str) or not FACTORY.fullmatch(factory_reference):
        raise DeploymentConfigurationError('Expected trusted module:factory')
    module, name = factory_reference.split(':')
    factory = getattr(importlib.import_module(module), name)
    if not callable(factory):
        raise DeploymentConfigurationError('Runtime factory must be callable')
    bindings = factory()
    if not isinstance(bindings, RuntimeBindings):
        raise DeploymentConfigurationError('Configured factory must return runtime bindings')
    if (transaction_db is not None and bindings.transaction_processor is not None
        and bindings.transaction_store is None):
        bindings = replace(bindings, transaction_store=TransactionStore(transaction_db))
    return create_application(bindings)

core_platform/free_resources.py.content:
"""
Module: core_platform.free_resources
Architectural Layer: Resource Ingestion & Metric Compliance Gate
Description: Owner-directed OCI free-resource incorporation. Checks usage tracking
metrics against fixed cloud allowance boundaries.
"""

from collections import Counter
from datetime import datetime, timezone
import json
import math
from pathlib import Path

CATALOG = Path(__file__).resolve().parents[1] / 'oci_free_resources.json'

def catalog():
    value = json.loads(CATALOG.read_text())
    if value.get('platform') != 'Sanders Dash & Seal' or value.get('schema') != 1:
        raise ValueError('Unexpected resource catalog identity')
    return value

def inventory_mapping(report):
    counts = Counter()
    for item in report.get('resources', []):
        if isinstance(item, dict) and isinstance(item.get('resource_type'), str):
            counts[item['resource_type'].casefold()] += 1

    resources = []
    for item in catalog()['resources']:
        inventory_types = item.get('inventory_types') or []
        if not isinstance(inventory_types, list):
            inventory_types = [inventory_types]
        observed = any(
            counts[name.casefold()] for name in inventory_types
            if isinstance(name, str)
        )
        resources.append({
            "resource_id": item.get('resource_id', item.get('id', '')),
            "resource_type": item.get('resource_type', ''),
            "count": sum(
                counts[name.casefold()] for name in inventory_types
                if isinstance(name, str)
            ),
            "observation_status": (
                'RELATED_METADATA_OBSERVED' if observed else 'NOT_OBSERVED'
            ),
        })

    return {
        "catalog_date": catalog()['catalog_date'],
        "scope": "PERMISSION_FILTERED_METADATA",
        "scan_complete": report.get('scan_complete') is True,
        "metered_usage_verified": False,
        "free_balance_verified": False,
        "cloud_changes_performed": False,
        "resources": resources,
    }

def allowance_comparison(resource_id, requested, usage=None, *, account_state='free_only'):
    """Advisory arithmetic over explicit comparable units, never a deployment gate."""
    usage = usage if usage is not None else {}

    entries = [item for item in catalog()['resources'] if item['id'] == resource_id]
    if not entries or not isinstance(requested, dict) or not requested:
        raise ValueError('Documented resource and named metrics required')

    limits = entries[0]['allowances']
    for key, value in requested.items():
        limit = limits.get(key)
        if (type(limit) not in (int, float) or not math.isfinite(limit) or limit < 0 or
            type(value) not in (int, float) or not math.isfinite(value) or value < 0 or
            key.startswith(('paid_or_trial_', 'groups_minimum_', 'groups_maximum_'))):
            raise ValueError('Explicit comparable documented metrics required')

    result = {
        "resource_id": resource_id,
        "status": "USAGE_UNKNOWN",
        "billing_verified": False,
        "deployment_authorized": False,
        "cloud_changes_performed": False,
        "comparisons": {}
    }

    if account_state == 'free_only':
        result['status'] = 'ACCOUNT_STATE_REQUIRES_SEPARATE_PROFILE'
        return result

    if not isinstance(usage, dict) or any(key not in usage for key in requested):
        return result

    for key, amount in requested.items():
        used = usage[key]
        if type(used) not in (int, float) or not math.isfinite(used) or used < 0:
            raise ValueError('Explicit nonnegative metered usage required')

        result['comparisons'][key] = {
            "observed_usage": used,
            "requested_addition": amount,
            "projected_usage": used + amount,
            "documented_allowance": limits[key]
        }

    # Correctly check projection sums against allowances within the dictionary values
    is_compliant = all(
        item['projected_usage'] <= item['documented_allowance']
        for item in result['comparisons'].values()
    )

    result['status'] = 'WITHIN_DOCUMENTED_AMOUNTS' if is_compliant else 'EXCEEDS_DOCUMENTED_AMOUNTS'
    return result

def report():
    return {
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "catalog": catalog(),
        "live_usage": "NOT_QUERIED",
        "cloud_changes_performed": False
    }

if __name__ == '__main__':
    pass

core_platform/global_time.py.content:
"""Global time handling for Sanders Dash & Seal.

Rules (real-world / global by design):
- Storage is always UTC. Only timezone-aware datetimes are accepted;
  naive datetimes raise :class:`NaiveDatetimeError` instead of being
  silently assumed to be local time or UTC.
- Display is per-user, by IANA timezone name (``ZoneInfo``). No
  hardcoded America/Denver / MST assumption anywhere in this module.
- DST transitions are handled honestly: an ambiguous local time
  (fall-back) resolves to the FIRST occurrence (fold=0) and is flagged;
  a nonexistent local time (spring-forward gap) is shifted forward to
  the first valid instant and flagged. Callers get the flag, never a
  silently wrong instant.

Stdlib only. No live calls, no keys.
"""

from __future__ import annotations

from datetime import datetime, time as dtime, timedelta, timezone
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

__all__ = [
    "NaiveDatetimeError",
    "UnknownTimezoneError",
    "AmbiguousTime",
    "NonexistentTime",
    "now_utc",
    "require_aware",
    "to_utc",
    "parse_iso8601",
    "serialize_utc",
    "display_in_timezone",
    "resolve_timezone",
    "next_daily_occurrence",
    "is_ambiguous",
    "is_nonexistent",
]

UTC = timezone.utc


class NaiveDatetimeError(ValueError):
    """Raised when a naive (tzinfo-less) datetime is supplied."""


class UnknownTimezoneError(ValueError):
    """Raised when an IANA timezone name cannot be resolved."""


class AmbiguousTime(ValueError):
    """A local time that occurs twice (fall-back DST transition)."""


class NonexistentTime(ValueError):
    """A local time that never occurs (spring-forward DST gap)."""


def resolve_timezone(name: str) -> ZoneInfo:
    """Resolve an IANA timezone name, raising UnknownTimezoneError."""
    if not isinstance(name, str) or not name.strip():
        raise UnknownTimezoneError("empty timezone name")
    try:
        return ZoneInfo(name.strip())
    except (ZoneInfoNotFoundError, ValueError) as exc:
        raise UnknownTimezoneError(f"unknown IANA timezone: {name!r}") from exc


def now_utc() -> datetime:
    """Current instant, timezone-aware, in UTC."""
    return datetime.now(UTC)


def require_aware(value: datetime, *, what: str = "datetime") -> datetime:
    """Return *value* if aware, else raise NaiveDatetimeError."""
    if not isinstance(value, datetime):
        raise TypeError(f"{what} must be a datetime, got {type(value).__name__}")
    if value.tzinfo is None or value.utcoffset() is None:
        raise NaiveDatetimeError(
            f"{what} is naive (no tzinfo); pass a timezone-aware datetime"
        )
    return value


def to_utc(value: datetime) -> datetime:
    """Convert an aware datetime to UTC. Naive input raises."""
    return require_aware(value).astimezone(UTC)


def serialize_utc(value: datetime) -> str:
    """Serialize an aware datetime as ISO-8601 UTC, e.g. 2026-11-13T17:48:36Z."""
    return to_utc(value).isoformat(timespec="seconds").replace("+00:00", "Z")


def parse_iso8601(value: str) -> datetime:
    """Parse an ISO-8601 string. A timezone offset (or Z) is REQUIRED.

    Naive strings raise NaiveDatetimeError. The result is normalized
    to UTC.
    """
    if not isinstance(value, str) or not value.strip():
        raise ValueError("empty ISO-8601 string")
    text = value.strip().replace("Z", "+00:00").replace("z", "+00:00")
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError as exc:
        raise ValueError(f"invalid ISO-8601 datetime: {value!r}") from exc
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise NaiveDatetimeError(
            f"ISO-8601 datetime {value!r} has no timezone offset; "
            "storage requires an explicit offset (use Z for UTC)"
        )
    return parsed.astimezone(UTC)


def display_in_timezone(value: datetime, tz_name: str) -> datetime:
    """Render an aware datetime in the user's IANA timezone."""
    return require_aware(value).astimezone(resolve_timezone(tz_name))


def _roundtrip_offset(local_naive: datetime, tz: ZoneInfo) -> timedelta:
    return local_naive.replace(tzinfo=tz).utcoffset()


def is_ambiguous(local_naive: datetime, tz: ZoneInfo) -> bool:
    """True if the naive local time occurs twice (fall-back).

    Nonexistent (spring-forward gap) times are NOT ambiguous.
    """
    if is_nonexistent(local_naive, tz):
        return False
    first = local_naive.replace(tzinfo=tz, fold=0)
    second = local_naive.replace(tzinfo=tz, fold=1)
    return first.utcoffset() != second.utcoffset()


def is_nonexistent(local_naive: datetime, tz: ZoneInfo) -> bool:
    """True if the naive local time never occurs (spring-forward gap)."""
    candidate = local_naive.replace(tzinfo=tz, fold=0)
    # A nonexistent time round-trips to a different wall-clock time.
    return candidate.astimezone(UTC).astimezone(tz).replace(tzinfo=None) != local_naive


def next_daily_occurrence(
    hour: int,
    minute: int,
    tz_name: str,
    *,
    after: datetime | None = None,
) -> tuple[datetime, str]:
    """Next daily occurrence of a local wall-clock time.

    Returns ``(aware_utc_datetime, status)`` where status is one of:
    - ``"ok"`` — unambiguous, exists;
    - ``"ambiguous_first"`` — fall-back day; the FIRST occurrence is used;
    - ``"nonexistent_shifted"`` — spring-forward gap; shifted forward to
      the first valid instant after the gap (same date, later clock time).

    ``after`` must be aware (defaults to now, UTC). The result is UTC.
    """
    if not 0 <= hour <= 23 or not 0 <= minute <= 59:
        raise ValueError(f"invalid local time {hour:02d}:{minute:02d}")
    tz = resolve_timezone(tz_name)
    after_utc = to_utc(after) if after is not None else now_utc()
    after_local = after_utc.astimezone(tz)

    for day_offset in range(0, 3):
        day = (after_local + timedelta(days=day_offset)).date()
        naive = datetime.combine(day, dtime(hour, minute))
        status = "ok"
        if is_nonexistent(naive, tz):
            # Shift forward minute-by-minute to the first valid instant.
            probe = naive
            for _ in range(0, 180):
                probe += timedelta(minutes=1)
                if not is_nonexistent(probe, tz):
                    naive = probe
                    break
            status = "nonexistent_shifted"
        elif is_ambiguous(naive, tz):
            status = "ambiguous_first"  # fold=0 below
        candidate = naive.replace(tzinfo=tz, fold=0).astimezone(UTC)
        if candidate > after_utc:
            return candidate, status
        # Same-day time already passed; try tomorrow (loop continues).
    raise RuntimeError("could not find a next daily occurrence within 3 days")

core_platform/google_workspace_adapters..content:
"""Optional Google Workspace adapters (Docs / Sheets / Gmail / Calendar).

Google Docs, Sheets, Gmail and Calendar are already connected to
Muse for this owner.  These adapters are the *optional* bridge for
the platform to use them where they actually help:

* Grantwriter drafting -> Google Docs (export a finished draft).
* Scheduling -> Google Calendar (create a deadline/reminder event).
* Notifications -> Gmail (send a status email).

Design, stated honestly
-----------------------
* No Google library is imported at module import time and no live
  call is made by this module.  Each adapter takes an injected
  client object (the connected Google service client, or a fake in
  tests) exposing one small method.  Without a client, every action
  raises ``ValueError("... not configured ...")`` and ``status()``
  reports ``MISSING_CLIENT`` — never a silent no-op, never a
  fabricated document/event/email.
* The injected-client shape is deliberately tiny so the real
  connected client can be wrapped by the caller without this module
  knowing Google's API surface:
  - Docs:    ``create_document(title, text) -> {"id": ..., "url": ...}``
  - Sheets:  ``append_row(spreadsheet_id, range, values) -> {"updated": n}``
  - Gmail:   ``send_message(to, subject, body) -> {"id": ...}``
  - Calendar: ``create_event(summary, start, end, description="") -> {"id": ...}``
* No credentials are handled here at all: authentication lives with
  the already-connected Google account; this module never sees a
  token, key or password.
"""

from __future__ import annotations

from typing import Any


class GoogleWorkspaceNotConfigured(ValueError):
    """Raised when a Workspace action is attempted without a client."""


class _BaseAdapter:
    service: str = "google-workspace"
    client_method: str = ""

    def __init__(self, client=None) -> None:
        self._client = client

    @property
    def configured(self) -> bool:
        return self._client is not None

    def status(self) -> dict[str, Any]:
        return {
            "service": self.service,
            "configured": self.configured,
            "live_status": "READY" if self.configured else "MISSING_CLIENT",
            "note": (
                "Client supplied; live calls go through the connected "
                "Google account."
                if self.configured
                else "No client supplied; pass the connected Google "
                "service client to enable this adapter. No live call "
                "has been made."
            ),
        }

    def _require_client(self):
        if self._client is None:
            raise GoogleWorkspaceNotConfigured(
                f"{self.service} client is not configured; pass the "
                "connected Google service client to enable it"
            )
        method = getattr(self._client, self.client_method, None)
        if not callable(method):
            raise TypeError(
                f"Google client must expose {self.client_method}()"
            )
        return method


class GoogleDocsAdapter(_BaseAdapter):
    """Optional export target for Grantwriter drafts."""

    service = "google-docs"
    client_method = "create_document"

    def create_document(self, *, title: str, text: str) -> dict[str, Any]:
        if not title.strip() or not text.strip():
            raise ValueError("title and text must not be empty")
        create = self._require_client()
        result = create(title, text)
        if not isinstance(result, dict):
            raise ValueError("docs client returned an unexpected result")
        return {"service": self.service, **result}


class GoogleSheetsAdapter(_BaseAdapter):
    """Optional ledger/log target (e.g. grant pipeline, payment log)."""

    service = "google-sheets"
    client_method = "append_row"

    def append_row(
        self, *, spreadsheet_id: str, range: str, values: list[Any]
    ) -> dict[str, Any]:
        if not spreadsheet_id.strip() or not range.strip():
            raise ValueError("spreadsheet_id and range must not be empty")
        if not isinstance(values, list) or not values:
            raise ValueError("values must be a non-empty list")
        append = self._require_client()
        result = append(spreadsheet_id, range, values)
        if not isinstance(result, dict):
            raise ValueError("sheets client returned an unexpected result")
        return {"service": self.service, **result}


class GmailAdapter(_BaseAdapter):
    """Optional notification sender (status / deadline reminders)."""

    service = "gmail"
    client_method = "send_message"

    def send_notification(
        self, *, to: str, subject: str, body: str
    ) -> dict[str, Any]:
        if "@" not in to or not subject.strip() or not body.strip():
            raise ValueError("to/subject/body must be valid and non-empty")
        send = self._require_client()
        result = send(to, subject, body)
        if not isinstance(result, dict):
            raise ValueError("gmail client returned an unexpected result")
        return {"service": self.service, **result}


class GoogleCalendarAdapter(_BaseAdapter):
    """Optional scheduler (grant deadlines, review reminders)."""

    service = "google-calendar"
    client_method = "create_event"

    def create_event(
        self,
        *,
        summary: str,
        start: str,
        end: str,
        description: str = "",
    ) -> dict[str, Any]:
        if not summary.strip() or not start.strip() or not end.strip():
            raise ValueError("summary, start and end must not be empty")
        create = self._require_client()
        result = create(summary, start, end, description)
        if not isinstance(result, dict):
            raise ValueError("calendar client returned an unexpected result")
        return {"service": self.service, **result}


def workspace_status(adapters: dict[str, _BaseAdapter] | None = None) -> dict[str, Any]:
    """Status of all four optional adapters. No live calls."""
    supplied = adapters or {}
    names = ("google-docs", "google-sheets", "gmail", "google-calendar")
    out: dict[str, Any] = {}
    for name in names:
        adapter = supplied.get(name)
        out[name] = (
            adapter.status()
            if adapter is not None
            else {
                "service": name,
                "configured": False,
                "live_status": "MISSING_CLIENT",
                "note": "No client supplied. No live call has been made.",
            }
        )
    return out


__all__ = [
    "GoogleWorkspaceNotConfigured",
    "GoogleDocsAdapter",
    "GoogleSheetsAdapter",
    "GmailAdapter",
    "GoogleCalendarAdapter",
    "workspace_status",
]

core_platform/hotswap.py.content:
"""
Module: core_platform.hotswap
Architectural Layer: L15+ Upgrade Orchestration Primitives (Docker Hotswap Engine)
Description: Dependency-safe zero-downtime hot-swap deployment coordinator.
             Performs safe multi-stage rollouts, continuous health sweeps,
             and automated zero-downtime microservice cutovers.
"""

from dataclasses import dataclass
import hashlib
import json
import re
from .upgrade_sidecar import require_core_laws

class HotSwapDenied(Exception):
    pass

DIGEST = re.compile(r'^(?:sha256:)?[A-Za-z0-9_.-]{8,}(?:@[A-Fa-f0-9]{64})?$')
IDENT = re.compile(r'^[A-Za-z0-9_-]{1,127}$')

@dataclass(frozen=True)
class Workload:
    name: str
    role: str
    current_image: str
    candidate_image: str
    dependencies: tuple = ()

    def validate(self):
        if not IDENT.fullmatch(self.name) or self.role not in ('frontend', 'backend', 'sidecar'):
            raise HotSwapDenied("Invalid workload identity or role")
        if not DIGEST.fullmatch(self.current_image) or not DIGEST.fullmatch(self.candidate_image):
            raise HotSwapDenied("Only immutable container image digests are permitted")
        if not isinstance(self.dependencies, tuple) or any(not isinstance(d, str) for d in self.dependencies):
            raise HotSwapDenied("Invalid dependency inventory profile")

@dataclass(frozen=True)
class UpgradePlan:
    release_id: str
    workloads: tuple
    inversion_record: dict

    def ordered(self):
        """Resolves topological dependencies cleanly using clear nonlocal tracking scopes."""
        by_name = {}
        for w in self.workloads:
            w.validate()
            if w.name in by_name:
                raise HotSwapDenied("Duplicate workload identifier discovered")
            by_name[w.name] = w

        ordered = []
        visited = set()
        visiting = set()

        def visit(name):
            # Explicitly claim parent scope context bounds to prevent UnboundLocalError crashes
            nonlocal ordered, visited, visiting

            if name in visiting:
                raise HotSwapDenied("Circular dependency cycle detected inside container matrix")
            if name in visited:
                return
            if name not in by_name:
                raise HotSwapDenied("Missing dependency declaration element across runtime layout")

            visiting.add(name)
            for dep in by_name[name].dependencies:
                visit(dep)

            visiting.remove(name)
            visited.add(name)
            ordered.append(by_name[name])

        for name in by_name:
            visit(name)

        return tuple(ordered)

    def fingerprint(self):
        ordered = self.ordered()
        payload = {
            "release_id": self.release_id,
            "workloads": [
                {
                    "name": w.name,
                    "role": w.role,
                    "current_image": w.current_image,
                    "candidate_image": w.candidate_image,
                    "dependencies": list(w.dependencies)
                } for w in ordered
            ],
            "inversion_record": self.inversion_record
        }
        return hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()).hexdigest()

class GovernedHotswap:
    """Deploy dependency order, health-check, cut-over, verify, rollback loop matrix."""

    def __init__(self, deployment, routing, audit, authorize, core_laws=None):
        if core_laws is not None:
            require_core_laws(core_laws)
        self.deployment = deployment
        self.routing = routing
        self.audit = audit
        self.authorize = authorize

    def run(self, plan):
        if not isinstance(plan, UpgradePlan):
            raise HotSwapDenied("Invalid upgrade plan blueprint parameters")

        ordered = plan.ordered()
        fingerprint = plan.fingerprint()

        if self.authorize(plan, fingerprint) is not True:
            raise HotSwapDenied("Independent Twin-Gate / PBD production authorization failure")

        started = []
        switched = []
        try:
            self.audit.preserve({"stage": "UPGRADE_START", "release_id": plan.release_id, "fingerprint": fingerprint})

            # Step 1: Sequential Canary Deployment & Health Verification
            for w in ordered:
                self.deployment.start_candidate(w)
                started.append(w)
                if not self.deployment.healthy(w):
                    raise HotSwapDenied(f"Workload canary verification health metrics dropped: {w.name}")

                self.routing.cutover(w)
                switched.append(w)
                if not self.routing.verified(w):
                    raise HotSwapDenied(f"Traffic routing loop check verification failed: {w.name}")

                self.audit.preserve({"stage": "COMPONENT_HOTSWAP_SUCCESS", "workload": w.name})

            return "LIVE_VERIFIED"

        except Exception as error:
            # Step 2: Strict Fail-Closed Safe Rollback Sequences
            self.audit.preserve({"stage": "UPGRADE_CRITICAL_FAILURE", "error": str(error)})
            rollback_errors = []

            for w in reversed(switched):
                try:
                    self.routing.rollback(w)
                except Exception as exc:
                    rollback_errors.append((w.name, "routing", type(exc).__name__))

            for w in reversed(started):
                try:
                    self.deployment.stop_candidate(w)
                except Exception as exc:
                    rollback_errors.append((w.name, "deployment", type(exc).__name__))

            if rollback_errors:
                self.audit.preserve({"stage": "ROLLBACK_CORRUPTED", "errors": rollback_errors})
                raise HotSwapDenied("Rollback incomplete: cluster configuration split-brain state detected") from error
            raise

if __name__ == "__main__":
    pass

core_platform/identity_continuity.py.content:
"""
Module: core_platform.identity_continuity
Architectural Layer: Identity Continuity Guard & Access Control Enforcer
Description: Enforces strict asset-bound execution tracking limits. Verifies that
             no update or modification removes historic capabilities or drops active guards.
"""

from copy import deepcopy

class IdentityContinuityDenied(ValueError):
    pass

def require_continuity(baseline, candidate):
    if not isinstance(baseline, dict) or not isinstance(candidate, dict):
        raise IdentityContinuityDenied('Identity records required')

    for field in ('identity_id', 'role', 'authority_boundary'):
        if not baseline.get(field) or candidate.get(field) != baseline[field]:
            raise IdentityContinuityDenied('Identity or authority boundary changed')

    for field in ('capabilities', 'protections'):
        old_list = baseline.get(field)
        new_list = candidate.get(field)

        for value in (old_list, new_list):
            if not isinstance(value, list) or not value or any(
                not isinstance(item, str) or not item.strip() for item in value
            ) or len(set(value)) != len(value):
                raise IdentityContinuityDenied('Explicit capability/protection inventories required')

        # FIX: Convert raw lists into native set representations to safely verify sub-membership bounds
        if not set(old_list).issubset(set(new_list)):
            raise IdentityContinuityDenied('Historical capability or protection removed')

    return True

class IdentityPreservingExecutor:
    """Provides secure identity encapsulation boundaries over runtime resource pools."""

    def __init__(self, executor, baselines, candidate_verifier):
        if not isinstance(baselines, dict) or not baselines or not callable(candidate_verifier):
            raise IdentityContinuityDenied('Trusted inventory and verifier required')

        identities = []
        for baseline in baselines.values():
            require_continuity(baseline, baseline)
            identities.append(baseline['identity_id'])

        if len(set(identities)) != len(identities):
            raise IdentityContinuityDenied('Components must retain distinct identities')

        self._baselines = deepcopy(baselines)
        self._executor = executor
        self._verifier = candidate_verifier

    def stage(self, record, artifact_path):
        trusted_record = deepcopy(record)
        baseline = self._baselines.get(trusted_record.get('component'))
        if baseline is None:
            raise IdentityContinuityDenied('Unregistered component')

        candidate = self._verifier(deepcopy(trusted_record), artifact_path)
        require_continuity(baseline, candidate)
        return self._executor.stage(trusted_record, artifact_path)

    def verify(self, self_record):
        return self._executor.verify(self_record)

    def rollback(self, self_record):
        # Recovery remains available, including while an owner halt is active.
        return self._executor.rollback(self_record)

core_platform/l15_repair_engine.py.content:
"""
Module: core_platform.l15_repair_engine
Architectural Layer: Sanders Sidecar L15 Repair Evaluation Matrix
Description: Safe dry-run simulation and structural repair evaluation engine.
             Processes multi-hypothesis temporal and causal counterfactual records.
             Never executes destructive commands or exercises runtime production authority.
"""

from dataclasses import dataclass
import hashlib
import json

DIMENSIONS = (
    "causal", "temporal", "counterfactual", "constraint", "systems",
    "adversarial", "probabilistic", "deterministic_verification",
    "multi_hypothesis", "dependency_blast_radius", "security",
    "governance", "self_critique", "state_reconciliation", "proof_of_outcome"
)

PHASES = (
    "observe", "verify", "diagnose", "simulate", "challenge",
    "authorize", "repair", "reconstruct", "verify_postcondition",
    "commit_or_rollback", "harden", "prove"
)

class RepairDenied(PermissionError):
    pass

def digest(data):
    return hashlib.sha256(json.dumps(data, sort_keys=True, separators=(',', ':'),
                         allow_nan=False).encode()).hexdigest()

def validate_evidence(evidence):
    if not isinstance(evidence, dict) or any(
        not isinstance(evidence.get(k), dict) or not evidence[k] for k in DIMENSIONS
    ):
        raise RepairDenied("All fifteen independent reasoning evidence records are required")
    # FIX: Corrected NameError from _digest to your defined digest function
    return digest({k: evidence[k] for k in DIMENSIONS})

@dataclass(frozen=True)
class RepairProposal:
    incident_id: str
    principal_id: str
    sidecar_id: str
    action: str
    capability: str
    preconditions: tuple
    blast_radius: tuple
    rollback_steps: tuple
    postconditions: tuple
    evidence_digest: str

    def __post_init__(self):
        if not all(isinstance(getattr(self, name), str) and getattr(self, name).strip()
            for name in ("incident_id", "principal_id", "sidecar_id",
                         "action", "capability", "evidence_digest")):
            raise RepairDenied("Complete repair identity and action required")

        if self.principal_id == self.sidecar_id:
            raise RepairDenied("Sidecar and principal identities must remain distinct")

        if len(self.evidence_digest) != 64 or any(
            c not in "0123456789abcdef" for c in self.evidence_digest
        ):
            raise RepairDenied("Invalid evidence digest")

        for name in ("preconditions", "blast_radius", "rollback_steps", "postconditions"):
            value = getattr(self, name)
            if not isinstance(value, tuple) or not value or any(
                not isinstance(v, str) or not v.strip() for v in value
            ):
                raise RepairDenied("Preconditions, blast radius, rollback and postconditions required")

class RepairSession:
    """Local hash-chained dry run. Never grants production execution or approval."""

    def __init__(self, proposal, evidence):
        if not isinstance(proposal, RepairProposal):
            raise RepairDenied("RepairProposal required")
        if validate_evidence(evidence) != proposal.evidence_digest:
            raise RepairDenied("Evidence mismatch")

        self.proposal = proposal
        self.phase = "observe"
        self.audit = []
        self._prior = '0' * 64
        self._record("created", {"incident_id": proposal.incident_id})

    def _record(self, kind, details):
        entry = {"prior": self._prior, "kind": kind, "details": details}
        entry["digest"] = digest(entry)
        self.audit.append(entry)
        self._prior = entry["digest"]

    def advance(self, next_phase, *, independent_review=False):
        current = PHASES.index(self.phase)
        if current + 1 >= len(PHASES) or PHASES[current + 1] != next_phase:
            raise RepairDenied("Out-of-order repair lifecycle transition")

        if next_phase in ("authorize", "repair", "commit_or_rollback"):
            raise RepairDenied("Authorization and execution unavailable in dry-run engine")

        if next_phase in ("challenge", "verify_postcondition", "prove") and independent_review is not True:
            raise RepairDenied("Independent review required")

        self.phase = next_phase
        self._record("phase", {"phase": next_phase})
        return self.phase

    def audit_valid(self):
        prior = '0' * 64
        for entry in self.audit:
            if entry.get("prior") != prior or entry.get("digest") != digest(
                {k: v for k, v in entry.items() if k != "digest"}
            ):
                return False
            prior = entry["digest"]
        return True

    def simulation_report(self):
        return {
            "incident_id": self.proposal.incident_id,
            "principal_id": self.proposal.principal_id,
            "sidecar_id": self.proposal.sidecar_id,
            "action": self.proposal.action,
            "blast_radius": list(self.proposal.blast_radius),
            "simulation_audit_trail": self.audit,
            "chain_valid": self.audit_valid()
        }

core_platform/lifecycle.py.content:
"""
Module: core_platform.lifecycle
Architectural Layer: Explicit Role Boundaries for the Twin-Gate Execution Lifecycle
Description: Coordinates high-level contract validation loops across QualityAgent,
             ITAIManager, and Minotaur cryptographic keys without exposing shell access.
"""

from .security import Denied, digest, verify
from .protocol import utc
from .artifacts import DevelopmentArtifactRunner

class QualityAgent:
    def __init__(self, trusted_public_key):
        self.key = trusted_public_key

    def verify_result(self, lease_id, result_bytes, attestation):
        expected = {'lease_id': lease_id, 'result_hash': digest(result_bytes)}
        if attestation.get('body') != expected:
            raise Denied('Quality Agent did not verify this result')
        verify(self.key, attestation.get('signature', ''), 'pbd-quality')

class ITAIManager:
    def __init__(self, trusted_public_key):
        self.key = trusted_public_key

    def reconcile(self, lease_id, result_bytes, attestation):
        expected = {'lease_id': lease_id, 'result_hash': digest(result_bytes)}
        if attestation.get('body') != expected:
            raise Denied('IT AI Manager did not reconcile this operation')
        verify(self.key, attestation.get('signature', ''), 'pbd-reconcile')

class Minotaur:
    def __init__(self, trusted_public_key):
        self.key = trusted_public_key

    def rewall(self, lease_id, result_bytes, attestation):
        expected = {'lease_id': lease_id, 'result_hash': digest(result_bytes)}
        if attestation.get('body') != expected:
            raise Denied('MINOTAUR did not confirm integrity')
        verify(self.key, attestation.get('signature', ''), 'pbd-integrity')

class LabyrinthShield:
    """Separate in-process containment state: OS isolation remains an absolute guard."""
    def __init__(self):
        self.quarantined = set()
        self.mode = 'GOVERNED'

    def contain(self, agent_key):
        self.quarantined.add(agent_key)
        self.mode = 'HUMANITARIAN'

    def check(self, agent_key):
        if self.mode != 'GOVERNED' or agent_key in self.quarantined:
            raise Denied('Shelter in place; human clearance required')

class GovernedLifecycle:
    def __init__(self, vault, validator, quality, manager, minotaur, shield, audit):
        if len({quality.key, manager.key, minotaur.key}) != 3:
            raise ValueError('Independent verification requires three distinct keys')
        if manager.key != vault.gate_keys['IT_AI_Manager_v15.0'] or minotaur.key != vault.gate_keys['MINOTAUR']:
            raise ValueError('Authority keys must match the Vault trust roots')
        self.vault = vault
        self.validator = validator
        self.audit = audit
        self.quality = quality
        self.manager = manager
        self.minotaur = minotaur
        self.shield = shield

    def run(self, lease_id, scope, payload, proof, artifact, runner,
            quality_check, reconcile_check, integrity_check):
        body = None
        status = 'DENIED'
        receipt = None
        execution_receipt = None
        started = utc(self.vault.clock())

        try:
            # Consumed authority can never be reused, including after partial failure
            body = self.vault.claim(lease_id, scope, payload, proof)
            self.shield.check(body['execution_binding']['agent_public_key'])

            if type(runner) is not DevelopmentArtifactRunner or runner.validator != self.validator:
                raise Denied('Unapproved execution runner')

            runner.validate(artifact, scope)
            if digest(artifact.source) != body['execution_binding']['artifact_hash']:
                raise Denied('Executable differs from the lease-bound cryptographic contract')

            self.audit.preserve({'event': 'EXECUTION_START', 'lease_id': lease_id, 'artifact': artifact.name})

            result = runner.execute(artifact, scope, payload)
            if not isinstance(result, bytes):
                raise Denied('Adapter result must be bytes')

            # Execute systematic Twin-Gate cryptographic confirmation checks
            self.quality.verify_result(lease_id, result, quality_check)
            self.manager.reconcile(lease_id, result, reconcile_check)
            self.minotaur.rewall(lease_id, result, integrity_check)

            receipt = {
                'quality': quality_check,
                'reconciliation': reconcile_check,
                'integrity': integrity_check
            }
            status = 'VERIFIED'
        except BaseException:
            if body:
                self.shield.contain(body['execution_binding']['agent_public_key'])
            raise
        finally:
            # FIX: Properly aligned exception handler blocks to prevent compile and parse crashes
            try:
                execution_receipt = {
                    'execution_metadata': {
                        'lease_id': lease_id,
                        'executed_by': body['agent_identity'] if body else 'UNKNOWN',
                        'started_at_utc': started,
                        'completed_at_utc': utc(self.vault.clock()),
                        'post_condition_verified': status == 'VERIFIED'
                    },
                    'attestations': receipt
                }
                execution_receipt = self.audit.preserve_execution('LICYCLE_SETTLED', execution_receipt)
            finally:
                self.vault.revoke(lease_id)
                self.audit.preserve({'event': 'AUTHORITY_REVOKED', 'lease_id': lease_id})

        return {'lease_id': lease_id, 'status': status, 'execution_receipt': execution_receipt}

core_platform/local_upgrade_executor.py.content:
"""
Local atomic artifact staging adapter for the Sanders Dash & Seal sidecar.

This is a filesystem staging executor, NOT a production process manager or
an independent authorization, AI inference, or OS sandbox service.
"""

import hashlib
import json
import os
from pathlib import Path
import shutil
import tempfile

class LocalUpgradeExecutor:
    def __init__(self, root):
        self.root = Path(root).resolve()
        self.root.mkdir(parents=True, exist_ok=True)

    def _component_dir(self, record):
        name = record["component"]
        if not isinstance(name, str) or not name or not all(
            c.isascii() and (c.isalnum() or c in "_-") for c in name
        ):
            raise ValueError("Invalid component")
        directory = self.root / name
        directory.mkdir(parents=True, exist_ok=True)
        return directory

    def _state(self, directory):
        state = directory / "state.json"
        if not state.exists():
            return {}
        return json.loads(state.read_text(encoding="utf-8"))

    def _write_state(self, directory, state):
        fd, tmp = tempfile.mkstemp(dir=directory, prefix=".state-")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as stream:
                json.dump(state, stream, sort_keys=True)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(tmp, directory / "state.json")
        finally:
            if os.path.exists(tmp):
                os.unlink(tmp)

    def stage(self, record, artifact_path):
        directory = self._component_dir(record)
        if self._state(directory).get("pending"):
            raise ValueError("Unverified upgrade already staged")
        source = Path(artifact_path)
        if not source.is_file() or source.is_symlink():
            raise ValueError("Regular source required")
        payload = source.read_bytes()
        actual = hashlib.sha256(payload).hexdigest()
        if actual != record["artifact_hash"]:
            raise ValueError("Artifact digest mismatch")
        current = directory / "current.bin"
        previous = directory / "previous.bin"
        if current.exists():
            shutil.copyfile(current, previous)
        fd, tmp = tempfile.mkstemp(dir=directory, prefix=".artifact-")
        try:
            with os.fdopen(fd, "wb") as stream:
                stream.write(payload)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(tmp, current)
        finally:
            if os.path.exists(tmp):
                os.unlink(tmp)
        self._write_state(directory, {
            "pending": True,
            "digest": actual,
            "previous": previous.exists(),
            "version": record["version"]
        })
        return {"staged": True, "sha256": actual, "mode": "local-dark"}

    def verify(self, record):
        directory = self._component_dir(record)
        state = self._state(directory)
        current = directory / "current.bin"
        if not state.get("pending") or not current.exists():
            return {"healthy": False}
        digest = hashlib.sha256(current.read_bytes()).hexdigest()
        if digest != record["artifact_hash"] or digest != state.get("digest"):
            return {"healthy": False}
        state["pending"] = False
        self._write_state(directory, state)
        return {"healthy": True, "sha256": digest, "scope": "artifact-integrity-only"}

    def rollback(self, record):
        directory = self._component_dir(record)
        state = self._state(directory)
        previous = directory / "previous.bin"
        current = directory / "current.bin"
        if not state.get("previous") or not previous.exists():
            return {"restored": False, "reason": "no prior baseline"}
        os.replace(previous, current)
        state["pending"] = False
        state["digest"] = hashlib.sha256(current.read_bytes()).hexdigest()
        state["previous"] = False
        self._write_state(directory, state)
        return {"restored": True, "sha256": state["digest"]}

