"""
Native Ed25519 document signature verification; not proof of notarial authority.
"""

import base64
from pathlib import Path
from .native_documents import NativeDocuments, DocumentDenied
import re
import sqlite3
import time
from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey

ID = re.compile(r'^[A-Za-z0-9_-]{1,128}$', re.ASCII)

class SignatureDenied(ValueError):
    pass

class NativeSignatures:
    def __init__(self, path, storage_dir=None):
        self.path = str(path)
        self.storage_dir = Path(storage_dir) if storage_dir is not None else Path(self.path).parent / 'native_documents'
        with sqlite3.connect(self.path) as db:
            db.execute("""CREATE TABLE IF NOT EXISTS native_document_signatures (
                session_id TEXT NOT NULL, signature_id TEXT NOT NULL,
                document_id TEXT NOT NULL, signer_id TEXT NOT NULL,
                document_digest TEXT NOT NULL, public_key BLOB NOT NULL,
                signature BLOB NOT NULL, recorded_at INTEGER NOT NULL,
                PRIMARY KEY(session_id, signature_id)
            );""")

    @staticmethod
    def _message(session_id, document_id, signer_id, digest):
        return f"SDS-NATIVE-SIGNATURE-V1\n{session_id}\n{document_id}\n{signer_id}\n{digest}".encode()

    def record(self, session_id, document_id, signature_id, signer_id, public_key_b64, signature_b64):
        if not all(isinstance(v, str) and ID.fullmatch(v) for v in (session_id, document_id, signature_id, signer_id)):
            raise SignatureDenied("Invalid identifier")
        try:
            key_bytes = base64.b64decode(public_key_b64, validate=True)
            sig_bytes = base64.b64decode(signature_b64, validate=True)
            if len(key_bytes) != 32 or len(sig_bytes) != 64:
                raise ValueError("Invalid key length")
        except (ValueError, TypeError) as exc:
            raise SignatureDenied(f"Invalid signature encoding: {exc}") from exc

        with sqlite3.connect(self.path, timeout=10) as db:
            db.execute("BEGIN IMMEDIATE;")
            state = db.execute("SELECT state FROM native_notarial_sessions WHERE session_id = ?;", (session_id,)).fetchone()
            if not state or state[0] != 'AWAITING_AUTHORITY':
                raise SignatureDenied("Session unavailable")
            row = db.execute("SELECT sha256 FROM native_documents WHERE session_id = ? AND document_id = ?;", (session_id, document_id)).fetchone()
            if not row:
                raise SignatureDenied("Document unavailable")
            digest = row[0]
            try:
                NativeDocuments(self.path, self.storage_dir).read(session_id, document_id)
            except DocumentDenied as exc:
                raise SignatureDenied("Stored document integrity failure") from exc
            try:
                Ed25519PublicKey.from_public_bytes(key_bytes).verify(sig_bytes, self._message(session_id, document_id, signer_id, digest))
            except (InvalidSignature, ValueError) as exc:
                raise SignatureDenied("Signature verification failed") from exc

            expected = (document_id, signer_id, digest, key_bytes, sig_bytes)
            existing = db.execute("SELECT document_id, signer_id, document_digest, public_key, signature FROM native_document_signatures WHERE session_id = ? AND signature_id = ?;", (session_id, signature_id)).fetchone()
            if existing and existing != expected:
                raise SignatureDenied("Conflicting signature identifier")
            if not existing:
                db.execute("INSERT INTO native_document_signatures (session_id, signature_id, document_id, signer_id, document_digest, public_key, signature, recorded_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?);",
                           (session_id, signature_id, document_id, signer_id, digest, key_bytes, sig_bytes, int(time.time())))
                db.commit()
        return {'session_id': session_id, 'signature_id': signature_id, 'document_sha256': digest, 'cryptographic_signature_verified': True, 'notarial_act_completed': False}

core_platform/oci_core_laws.py.content:
"""
Module: core_platform.upgrade_sidecar
Architectural Layer: Oracle Always Free Enforcement & Core Law Compliance Gateway
Description: Enforces Core Law 10 and Core Law 11 by validating all runtime resource allocations,
             infrastructure configurations, and transaction payloads against the locked 
             oci_free_resources.json catalog. Ensures 100% zero-cost Oracle Cloud compliance 
             with immutable SHA-256 auditing and SQLite persistence.
"""

import hashlib
import json
import os
import pathlib
import re
import sqlite3
import time
from datetime import datetime, timezone

class CoreLawViolation(ValueError):
    """Raised when an operation or configuration violates Core Law 10 or Core Law 11."""
    pass

class CoreLaws:
    """Enforces Core Law 10 and Core Law 11 compliance across Sanders Dash & Seal infrastructure."""

    def __init__(self, catalog_path):
        self.catalog_path = pathlib.Path(catalog_path)
        self.catalog = self._load_catalog()
        self._verify_core_laws()

    def _load_catalog(self):
        if not self.catalog_path.exists():
            raise FileNotFoundError(f"OCI Free Resources catalog not found at {self.catalog_path}")

        try:
            data = json.loads(self.catalog_path.read_text(encoding='utf-8'))
            return data
        except Exception as exc:
            raise CoreLawViolation(f"Failed to parse OCI free resources catalog: {exc}") from exc

    def _verify_core_laws(self):
        governing_10 = self.catalog.get("governing_core_law", {})
        governing_11 = self.catalog.get("governing_core_Law", {})

        if governing_10.get("number") != 10 or "Always Free" not in governing_10.get("text", ""):
            raise CoreLawViolation("Core Law 10 integrity violation: Catalog missing mandatory Always Free mandate.")

        if governing_11.get("number") != 11 or "actually use" not in governing_11.get("text", ""):
            raise CoreLawViolation("Core Law 11 integrity violation: Catalog missing mandatory operational enforcement mandate.")

    def validate_resource_allocation(self, resource_id, configuration_metrics):
        """
        Validates that a requested resource allocation strictly adheres to Oracle Always Free allowances
        and does not trigger paid tiers or unapproved resource footprints.
        """
        resources = {r["id"]: r for r in self.catalog.get("resources", [])}
        if resource_id not in resources:
            raise CoreLawViolation(f"Resource identifier '{resource_id}' is not mapped in the Always Free catalog.")

        res_spec = resources[resource_id]
        allowances = res_spec.get("allowances", {})

        for metric, limit in allowances.items():
            requested_val = configuration_metrics.get(metric)
            if requested_val is not None:
                if isinstance(limit, (int, float)) and requested_val > limit:
                    raise CoreLawViolation(
                        f"Core Law 10/11 Violation: Resource '{resource_id}' metric '{metric}' requested value {requested_val} "
                        f"exceeds Always Free allowance limit of {limit}."
                    )
        return True

def import_core_laws(path):
    catalog_file = pathlib.Path(path) / "oci_free_resources.json"
    return CoreLaws(catalog_file)

core_platform/operational_probes.py.content:
"""
Actual local probes for the operational observation cycle; no repair executor.
"""
import hashlib
import json
import math
from pathlib import Path
import shutil
import sqlite3
import time
from contextlib import closing
from urllib.request import Request, ProxyHandler, build_opener, HTTPRedirectHandler
from urllib.error import HTTPError

from .operational_runtime import readonly_database
from .upgrade_sidecar import CORE_LAWS

class NoRedirect(HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None

def http_probe(url, *, opener=None, clock=time.monotonic):
    # URLs are fixed by this module. Never taken from HTTP requests or model output.
    opener = opener or build_opener(ProxyHandler({}), NoRedirect())
    start = clock()
    try:
        with opener.open(Request(url, headers={'Host': 'sandersdashandseal.com'}), timeout=3) as response:
            code = response.status
            raw = response.read(8192)
        if len(raw) == 8192:
            return observation("UNKNOWN", "INVALID_HEALTH_RESPONSE")
        value = json.loads(raw)
        expected = "service_ready" if url.endswith("/readyz") else "process_alive"
        if code == 200 and isinstance(value, dict) and value.get(expected) is True:
            return observation("HEALTHY", "HTTP_VERIFIED", latency_ms=max(0, (clock()-start)*1000))
        return observation("FAULT", "HTTP_UNHEALTHY", http_status=code)
    except HTTPError as error:
        code = error.code
        error.close()
        return observation("FAULT", "HTTP_UNHEALTHY", http_status=code)
    except (OSError, ValueError):
        return observation("FAULT", "HTTP_UNAVAILABLE")

def database_probe(path):
    try:
        with closing(readonly_database(path)) as db:
            result = db.execute("PRAGMA quick_check;").fetchall()
        return observation("HEALTHY", "DATABASE_CHECKED") if result == [('ok',)] else observation("FAULT", "DATABASE_CORRUPT")
    except sqlite3.Error:
        return observation("FAULT", "DATABASE_UNAVAILABLE")

def source_probe(root):
    files = list((Path(root)/'core_platform').glob('*.py'))
    if not files:
        return observation("UNKNOWN", "SOURCE_NOT_OBSERVED")
    try:
        for path in files:
            manifest = Path(str(path)+'.pbd.json')
            if path.is_symlink() or manifest.is_symlink():
                return observation("FAULT", "SOURCE_INTEGRITY_MISMATCH")
            pair = json.loads(manifest.read_text())
            if (pair['body']['artifact'] != path.relative_to(root).as_posix()
                or pair['body']['payload_hash'] != hashlib.sha256(path.read_bytes()).hexdigest()):
                return observation("FAULT", "SOURCE_INTEGRITY_MISMATCH")
        return observation("HEALTHY", "SOURCE_HASHES_MATCH", files_checked=len(files))
    except (OSError, ValueError, KeyError, TypeError):
        return observation("FAULT", "SOURCE_PAIR_INVALID")

def integration_probe(path):
    with closing(readonly_database(path)) as db:
        rows = db.execute("SELECT state, COUNT(*) FROM provider_requests GROUP BY state;").fetchall()
    # Only report uncertain operations. Stored successful requests do not prove
    # credentials or external providers are currently connected.
    uncertain = sum(count for state, count in rows if state == 'UNCERTAIN')
    return observation("FAULT" if uncertain else "UNKNOWN",
                       "PROVIDER_RECONCILIATION_REQUIRED" if uncertain else "LIVE_PROVIDER_NOT_PROBED",
                       uncertain_requests=uncertain)

def backup_probe(path, clock=time.monotonic):
    path = Path(path)
    if not path.is_file() or path.is_symlink():
        return observation("UNKNOWN", "BACKUP_NOT_OBSERVED")
    value = json.loads(path.read_text())
    if (value.get("status") != "BACKUP_RESTORE_VERIFIED"
        or type(value.get("verified_at")) not in (int, float)
        or not math.isfinite(value["verified_at"]) or value["verified_at"] < 0
        or value["verified_at"] > clock() or value.get("databases_verified") != 2):
        return observation("UNKNOWN", "BACKUP_EVIDENCE_INVALID")
    return observation("HEALTHY", "BACKUP_RESTORE_OBSERVED", age_seconds=clock()-value["verified_at"])

def configured_probes(path, audit, *, root=None, backup_status="/run/sds/backup-status.json"):
    root = Path(root) if root is not None else Path(__file__).resolve().parents[1]

    def audit_probe():
        try:
            audit.verify_audit()
            return observation("HEALTHY", "LOCAL_AUDIT_CHAIN_CHECKED")
        except Exception:
            return observation("FAULT", "AUDIT_CHAIN_UNAVAILABLE")

    def config_probe():
        catalog = json.loads((root/'oci_free_resources.json').read_text())
        correct = item(CORE_LAWS) == catalog['governing_core_law']['number'] == 10
        return observation("HEALTHY" if correct else "FAULT", "TEN_LAWS_MATCH" if correct else "LAW_CONFIGURATION_MISMATCH")

    def disk_probe():
        usage = shutil.disk_usage(Path(path).parent)
        return observation("HEALTHY" if usage.free > 0 else "FAULT",
                           "DISK_SPACE_OBSERVED" if usage.free > 0 else "DISK_FULL", free_bytes=usage.free, total_bytes=usage.total)

    def support_probe():
        with closing(readonly_database(path)) as db:
            count = db.execute("SELECT COUNT(*) FROM ai_operational_incidents WHERE state='OPEN';").fetchone()[0]
        return observation("HEALTHY", "INCIDENT_INVENTORY_READ", open_incidents=count)

    def quality_probe():
        # This is a separate observation, never a signed Quality attestation.
        with closing(readonly_database(path)) as db:
            count = db.execute("SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name IN ('ai_observation_cycles');").fetchone()[0]
        return observation("HEALTHY" if count == 1 else "FAULT", "SUPERVISION_SCHEMA_CHECKED", tables=count)

    return {
        "uptime": lambda: http_probe("http://127.0.0.1:8000/healthz"),
        "application": lambda: http_probe("http://127.0.0.1:8000/readyz"),
        "database": lambda: database_probe(path),
        "deployment": lambda: source_probe(root),
        "infrastructure": disk_probe,
        "integration": lambda: integration_probe(path),
        "performance": lambda: http_probe("http://127.0.0.1:8000/healthz"),
        "backup": lambda: backup_probe(backup_status),
        "observability": audit_probe,
        "quality": quality_probe,
        "configuration": config_probe,
        "support": support_probe
    }

core_platform/operational_runtime.py.content:
"""
Durable operational observations, incidents and verified recovery history.

Observers are read-only maintenance functions, not independently deployed model
services or authorization authorities. A recovered observation never signs a
lease, changes source, or grants permission to repair a service.
"""

import json
import math
import sqlite3
import time
from pathlib import Path

AGENTS = (
    ("UptimeAgent", "uptime"), ("ApplicationAgent", "application"),
    ("DatabaseAgent", "database"), ("DeploymentAgent", "deployment"),
    ("InfrastructureAgent", "infrastructure"), ("IntegrationAgent", "integration"),
    ("PerformanceAgent", "performance"), ("BackupRecoveryAgent", "backup"),
    ("ObservabilityAgent", "observability"), ("QualityAgent", "quality"),
    ("ConfigurationAgent", "configuration"), ("ITSupportAgent", "support")
)
STATES = frozenset(("HEALTHY", "FAULT", "UNKNOWN"))

class ObservationError(ValueError):
    pass

def validated(value):
    if not isinstance(value, dict) or set(value) != {'state', 'code', 'metrics'}:
        raise ObservationError("Invalid observation")
    if value['state'] not in STATES:
        raise ObservationError("Invalid state")
    if not isinstance(value['code'], str) or not value['code']:
        raise ObservationError("Invalid code")
    if len(value['code']) > 80:
        raise ObservationError("Code too long")
    if any(c not in "ABCDEFGHIJKLMNOPQRSTUVWXYZ_0123456789" for c in value['code']):
        raise ObservationError("Invalid code characters")
    if not isinstance(value['metrics'], dict):
        raise ObservationError("Invalid metrics")
    # Metric values are counts/durations only. No logs, credentials, identifiers,
    # customer records or model-generated free text enter operational history.
    for key, number in value['metrics'].items():
        if not isinstance(key, str) or not key or len(key) > 64 \
            or not key.replace('_', '').isalnum() \
            or not key.replace('_', '').islower() \
            or type(number) not in (int, float) \
            or not math.isfinite(number) or number < 0:
            raise ObservationError("Invalid observation metric")
    raw = json.dumps(value, sort_keys=True, allow_nan=False)
    if len(raw) > 4096:
        raise ObservationError("Oversized observation")
    return json.loads(raw)

def observation(state, code, **metrics):
    return validated({'state': state, 'code': code, 'metrics': metrics})

class OperationalRuntime:
    def __init__(self, path, clock=time.monotonic):
        self.path, self.clock = str(path), clock
        with self.connect() as db:
            db.executescript("""
                CREATE TABLE IF NOT EXISTS ai_observation_cycles (
                    cycle_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    started REAL NOT NULL, finished REAL, state TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS ai_observer_state (
                    agent TEXT PRIMARY KEY, cycle_id INTEGER NOT NULL,
                    observed REAL NOT NULL, observation TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS ai_operational_incidents (
                    incident_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    agent TEXT NOT NULL, code TEXT NOT NULL, state TEXT NOT NULL,
                    opened_cycle INTEGER NOT NULL, closed_cycle INTEGER
                );
                CREATE UNIQUE INDEX IF NOT EXISTS ai_one_open_incident
                ON ai_operational_incidents(agent) WHERE state='OPEN';
                CREATE TABLE IF NOT EXISTS ai_observation_history (
                    cycle_id INTEGER NOT NULL, agent TEXT NOT NULL,
                    observation TEXT NOT NULL, PRIMARY KEY(cycle_id, agent)
                );
            """)

    def connect(self):
        return sqlite3.connect(self.path, timeout=10)

    def cycle(self, observers):
        """Run all twelve observers: one failure does not stop the others.

        A newer committed cycle wins over a slower older cycle. UNKNOWN never
        closes a prior fault. Only a later explicit HEALTHY observation does.
        """
        if not isinstance(observers, dict) or set(observers) != {key for _, key in AGENTS}:
            raise ObservationError("Unknown observer binding")
        with self.connect() as db:
            cycle = db.execute("INSERT INTO ai_observation_cycles (started, state) VALUES (?, 'RUNNING');",
                               (self.clock(),)).lastrowid

        samples = {}
        for agent, key in AGENTS:
            probe = observers.get(key)
            try:
                samples[agent] = (validated(probe()) if callable(probe) else
                                  observation('UNKNOWN', 'OBSERVER_NOT_CONNECTED'))
            except Exception:
                # Exception strings can include URLs, credentials and customer data.
                samples[agent] = observation('UNKNOWN', 'OBSERVER_FAILED')

        now = self.clock()
        with self.connect() as db:
            db.execute("BEGIN IMMEDIATE;")
            newest = db.execute("SELECT MAX(cycle_id) FROM ai_observation_cycles WHERE state='COMPLETED';").fetchone()[0]
            if newest is not None and newest > cycle:
                db.execute("UPDATE ai_observation_cycles SET finished=?,state=? WHERE cycle_id=?;",
                           (now, 'SUPERSEDED', cycle))
                return {'cycle_id': cycle, 'state': 'SUPERSEDED'}
            for agent, sample in samples.items():
                raw = json.dumps(sample, sort_keys=True)
                db.execute("INSERT INTO ai_observation_history VALUES (?,?,?);", (cycle, agent, raw))
                db.execute("INSERT OR REPLACE INTO ai_observer_state VALUES (?,?,?,?);",
                           (agent, cycle, now, raw))
                active = db.execute("SELECT incident_id FROM ai_operational_incidents WHERE agent=? AND state='OPEN';", (agent,)).fetchone()
                if sample['state'] == 'FAULT' and active is None:
                    db.execute("INSERT INTO ai_operational_incidents(agent,code,state,opened_cycle) VALUES (?,?,?,?);",
                               (agent, sample['code'], 'OPEN', cycle))
                elif sample['state'] == 'HEALTHY' and active is not None:
                    db.execute("UPDATE ai_operational_incidents SET state=?,closed_cycle=? WHERE incident_id=?;",
                               ('OBSERVED_RECOVERY', cycle, active[0]))
            db.execute("UPDATE ai_observation_cycles SET finished=?,state=? WHERE cycle_id=?;",
                       (now, 'COMPLETED', cycle))
            return {'cycle_id': cycle, 'state': 'COMPLETED'}

    def status(self):
        now = self.clock()
        with self.connect() as db:
            rows = {agent: (cycle, observed, json.loads(raw)) for agent, cycle, observed, raw \
                in db.execute("SELECT agent, cycle_id, observed, observation FROM ai_observer_state;")}
            latest = db.execute("SELECT cycle_id, finished FROM ai_observation_cycles WHERE state='COMPLETED' ORDER BY cycle_id DESC;").fetchall()
            recovered = db.execute("SELECT COUNT(*) FROM ai_operational_incidents WHERE state='OBSERVED_RECOVERY';").fetchone()[0]
            incidents = [dict(zip(('incident_id', 'agent', 'code', 'state', 'opened_cycle', 'closed_cycle'), row))
                         for row in db.execute("SELECT incident_id, agent, code, state, opened_cycle, closed_cycle FROM ai_operational_incidents WHERE state!='OBSERVED_RECOVERY';").fetchall()]
            return {
                'platform': 'Sanders Dash & Seal',
                'mode': 'READ_ONLY_OPERATIONAL_OBSERVATION',
                'model_inference': 'NOT_CONNECTED', 'autonomous_repair': 'NOT_CONNECTED',
                'independent_authority_services': 'NOT_CONNECTED',
                'last_completed_cycle': latest[0][0] if latest else None,
                'seconds_since_cycle': max(0, now - latest[0][1]) if latest else None,
                'observed_recoveries': recovered,
                'agents': {agent: {'agent': agent, 'kind': 'READ_ONLY_OBSERVER',
                           'cycle_id': rows.get(agent)[0] if agent in rows else None,
                           'seconds_since_observation': max(0, now - rows[agent][1]) if agent in rows else None,
                           'observation': rows.get(agent)[2] if agent in rows else observation('UNKNOWN', 'NOT_OBSERVED')}
                           for agent, _ in AGENTS},
                'incidents': incidents
            }

def readonly_database(path):
    return sqlite3.connect(Path(path).resolve().as_uri(), uri=True, timeout=2)

core_platform/pbd_validation.py.content:
"""Sanders Dash & Seal: signed PBD manifest verification.

Verification only. This module never executes a target script.
Production trust roots must be provisioned outside the repository.
"""
from __future__ import annotations
from dataclasses import dataclass
from hashlib import sha256
from pathlib import Path
import base64
import json

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey

class ManifestRejected(PermissionError):
    pass

def canonical_bytes(value: dict) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")

@dataclass(frozen=True)
class TrustedSigner:
    role: str
    key_id: str
    public_key: Ed25519PublicKey

class PBDScriptValidationEngine:
    """Fail-closed signature and file-integrity gate; no process execution."""
    def __init__(self, trust_roots: dict[str, TrustedSigner]):
        required = {"it_manager", "minotaur"}
        if set(trust_roots) != required:
            raise ValueError("Both independent trust roots are required")
        if trust_roots["it_manager"].key_id == trust_roots["minotaur"].key_id:
            raise ValueError("Twin-Gate signers must be distinct")
        self._trust = trust_roots

    def verify(self, executable: Path, manifest: Path, *, expected_scope: str) -> dict:
        executable = Path(executable)
        manifest = Path(manifest)
        if manifest != executable.with_name(executable.name + ".pbd.json"):
            raise ManifestRejected("PAIR_PATH_MISMATCH")
        if executable.suffix not in (".py", ".js", ".sh"):
            raise ManifestRejected("EXECUTABLE_TYPE_NOT_GOVERNED")
        try:
            doc = json.loads(manifest.read_text(encoding="utf-8"))
            body = doc["signed_body"]
            signatures = doc["signatures"]
            if not isinstance(body, dict) or not isinstance(signatures, dict):
                raise ManifestRejected("INVALID_MANIFEST_SHAPE")
            if body["platform"] != "Sanders Dash & Seal":
                raise ManifestRejected("PLATFORM_IDENTITY_MISMATCH")
            if body["artifact"] != executable.name:
                raise ManifestRejected("ARTIFACT_MISMATCH")
            if body["scope"] != expected_scope:
                raise ManifestRejected("SCOPE_MISMATCH")
            if body["max_execution_limit"] != 1:
                raise ManifestRejected("EXECUTION_BOUND_INVALID")
            if body["sha256"] != sha256(executable.read_bytes()).hexdigest():
                raise ManifestRejected("PAYLOAD_HASH_MISMATCH")
            message = canonical_bytes(body)
            for role in ("it_manager", "minotaur"):
                signer = self._trust[role]
                item = signatures[role]
                if item["key_id"] != signer.key_id:
                    raise ManifestRejected("UNTRUSTED_SIGNER:" + role)
                signature = base64.b64decode(item["signature"], validate=True)
                signer.public_key.verify(signature, message)
            return {"verified": True, "artifact": executable.name,
                    "scope": expected_scope, "payload_sha256": body["sha256"]}
        except ManifestRejected:
            raise
        except (OSError, ValueError, KeyError, TypeError, InvalidSignature) as exc:
            raise ManifestRejected("SIGNATURE_OR_MANIFEST_INVALID") from exc

core_platform/pipeline_api.py.content:
"""Python authority and durable receipts for the owner-selected Node transport.

Connecting code: adapters are independent production authority, not identities
claimed by Node. A processor validates its operation and writes business state
using the supplied SQLite connection. No generic payload grants notarial power.
"""
import hashlib
import json
from pathlib import Path
import re
import sqlite3
import time
import uuid


IDENT = re.compile(r'[A-Za-z0-9_.-]{1,128}', re.ASCII)


class TransactionRejected(ValueError):
    pass


class TransactionStore:
    def __init__(self, path):
        self.path = str(path)
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        with self.connect() as db:
            db.execute('''CREATE TABLE IF NOT EXISTS pipeline_receipts (
                actor TEXT NOT NULL, request_id TEXT NOT NULL,
                fingerprint TEXT NOT NULL, receipt TEXT NOT NULL,
                PRIMARY KEY(actor, request_id))''')

    def connect(self):
        db = sqlite3.connect(self.path, timeout=5)
        db.execute('PRAGMA foreign_keys=ON')
        return db

    def process(self, transaction, actor, processor):
        if (not isinstance(transaction, dict)
                or not isinstance(transaction.get('request_id'), str)
                or not IDENT.fullmatch(transaction['request_id'])):
            raise TransactionRejected('request_id required')
        canonical = json.dumps(transaction, sort_keys=True, separators=(',', ':'), allow_nan=False)
        fingerprint = hashlib.sha256(canonical.encode()).hexdigest()
        with self.connect() as db:
            db.execute('BEGIN IMMEDIATE')
            previous = db.execute('SELECT fingerprint,receipt FROM pipeline_receipts '
                'WHERE actor=? AND request_id=?', (actor, transaction['request_id'])).fetchone()
            if previous:
                if previous[0] != fingerprint:
                    raise TransactionRejected('Conflicting request reuse')
                return json.loads(previous[1])
            # Business validation, human authority and auditing remain obligations
            # of the trusted processor. External irreversible effects require an
            # outbox/idempotent dispatcher, not a network call inside this commit.
            result = processor(transaction, actor, db)
            if not isinstance(result, dict):
                raise TransactionRejected('Processor must provide a validated result')
            receipt = {'receipt_id': uuid.uuid4().hex,
                'request_id': transaction['request_id'], 'recorded_at': int(time.time()),
                'result': result}
            encoded = json.dumps(receipt, separators=(',', ':'), allow_nan=False)
            if len(encoded.encode()) > 65536:
                raise TransactionRejected('Receipt too large')
            db.execute('INSERT INTO pipeline_receipts VALUES (?,?,?,?)',
                (actor, transaction['request_id'], fingerprint, encoded))
        return receipt


def create_pipeline_app(authenticate=None, processor=None, release_verifier=None, store=None):
    def app(env, start):
        def respond(status, payload):
            raw = json.dumps(payload, separators=(',', ':')).encode()
            start(status, [('Content-Type', 'application/json'),
                ('Content-Length', str(len(raw))), ('Cache-Control', 'no-store')])
            return [raw]
        try:
            ready = (callable(authenticate) and callable(release_verifier)
                     and release_verifier() is True)
        except Exception:
            ready = False
        if not ready:
            return respond('503 Service Unavailable', {'error': 'authority_unavailable'})
        if env.get('REQUEST_METHOD') != 'POST':
            return respond('405 Method Not Allowed', {'error': 'post_required'})
        path = env.get('PATH_INFO')
        if path not in ('/api/auth/verify', '/api/transactions/process'):
            return respond('404 Not Found', {'error': 'not_found'})
        data = None
        authorization = env.get('HTTP_AUTHORIZATION')
        if path == '/api/transactions/process':
            if processor is None or store is None:
                return respond('503 Service Unavailable', {'error': 'processor_unavailable'})
            if env.get('CONTENT_TYPE', '').split(';')[0].strip() != 'application/json':
                return respond('415 Unsupported Media Type', {'error': 'json_required'})
            try:
                length = int(env.get('CONTENT_LENGTH', '0'))
                if not 0 < length <= 1048576:
                    raise ValueError('length')
                raw = env['wsgi.input'].read(length)
                if len(raw) != length:
                    raise ValueError('short body')
                def invalid_constant(value):
                    raise ValueError('Nonfinite JSON')
                data = json.loads(raw, parse_constant=invalid_constant)
                if not isinstance(data, dict) or set(data) != {'transaction', 'session'}:
                    raise ValueError('envelope')
                session = data['session']
                if not isinstance(session, dict) or set(session) != {'authorization'}:
                    raise ValueError('session')
                authorization = session['authorization']
            except (ValueError, TypeError, KeyError, UnicodeError):
                return respond('400 Bad Request', {'error': 'invalid_request'})
        if (not isinstance(authorization, str) or not 1 <= len(authorization) <= 4096
                or any(ord(c) < 32 or ord(c) > 126 for c in authorization)):
            return respond('401 Unauthorized', {'error': 'session_unavailable'})
        # Reconstruct credentials only, never accept a forwarded actor/role.
        authentication_env = dict(env, HTTP_AUTHORIZATION=authorization)
        for key in ('HTTP_COOKIE', 'HTTP_X_USER', 'HTTP_X_ROLE', 'HTTP_X_FORWARDED_USER'):
            authentication_env.pop(key, None)
        try:
            actor = authenticate(authentication_env)
        except Exception:
            actor = None
        if not isinstance(actor, str) or not IDENT.fullmatch(actor):
            return respond('401 Unauthorized', {'error': 'session_unavailable'})
        if path == '/api/auth/verify':
            # Internal response to Node only; no invented session issuer. Every
            # submission revalidates the original credential independently.
            return respond('200 OK', {'authorization': authorization})
        try:
            receipt = store.process(data['transaction'], actor, processor)
            return respond('200 OK', receipt)
        except (TransactionRejected, ValueError, TypeError):
            return respond('422 Unprocessable Entity', {'error': 'transaction_rejected'})
        except Exception:
            return respond('503 Service Unavailable', {'error': 'transaction_unavailable'})
    return app

core_platform/platform_integration.py.content:
"""
Module: core_platform.platform_integration
Architectural Layer: MASTER-Governed System Integration Boundary
Description: Connects existing intake, human authority review, technical dispatch, 
             and upgrade sidecars without merging their independent authority domains.
             Guarantees fail-closed orchestration metrics.
"""

from .upgrade_sidecar import require_core_laws

class IntegrationDenied(Exception):
    pass

class SandersDashSealIntegration:
    """Fail-closed composition of independently governed existing components."""

    PLATFORM = 'Sanders Dash & Seal'

    def __init__(self, cases, authority, dispatcher, sidecar, audit, core_laws=None):
        # Gracefully handle cold-start bootstrap phases where core_laws is uninitialized
        if core_laws is not None:
            require_core_laws(core_laws)

        components = (cases, authority, dispatcher, sidecar, audit)
        if any(component is None for component in components):
            raise IntegrationDenied('All five independent components are required')

        # Ensure all registered components are separate instances to preserve domain boundaries
        if len({id(component) for component in components}) != len(components):
            raise IntegrationDenied('Independent roles cannot be merged')

        if authority.cases is not cases:
            raise IntegrationDenied('Authority review must use the same case registry')

        if dispatcher.audit is not audit or authority.audit is not audit:
            raise IntegrationDenied('Shared glass-box evidence boundary required')

        self.cases = cases
        self.authority = authority
        self.dispatcher = dispatcher
        self.sidecar = sidecar
        self.audit = audit

    def intake(self, case_id, jurisdiction, service, requester):
        self.audit.preserve('stage', 'CASE_INTAKE_INTENT', 'case_id', case_id,
                           'platform', self.PLATFORM)
        result = self.cases.create(case_id, jurisdiction, service, requester)
        self.audit.preserve('stage', 'CASE_AWAITING_HUMAN_REVIEW',
                           'case_id', case_id, 'status', result['status'])
        return result

    def human_review(self, case_id, reviewer, notary_identity, evidence):
        result = self.authority.review(case_id, reviewer, notary_identity, evidence)
        if result.get('notarial_act_executed') is not False:
            raise IntegrationDenied('Review cannot imply a notarial act')
        return result

    def request_technical_work(self, task_id, role, capability, component, specification_ref, evidence):
        if not specification_ref.startswith('MASTER '):
            raise IntegrationDenied('Technical work must reference MASTER')
        return self.dispatcher.submit(task_id, role, capability, component, specification_ref, evidence)

    def propose_upgrade(self, sample_id, component, version, artifact_hash, evidence):
        if not isinstance(evidence, dict) or not evidence.get('master_section'):
            raise IntegrationDenied('MASTER section traceability required')
        self.audit.preserve('stage', 'UPGRADE_INTENT', 'request_id', sample_id,
                           'component', component,
                           'master_section', evidence['master_section'])
        return self.sidecar.propose(sample_id, component, version, artifact_hash, evidence)

    def execute_notarial_act(self, *args, **kwargs):
        raise IntegrationDenied('Independent live provider and jurisdiction authority required')

    def deploy(self, *args, **kwargs):
        raise IntegrationDenied('Signed PBD, Twin-Gate, Vault and production runtime required')

core_platform/protocol.py.content:
"""
Module: core_platform.protocol
Architectural Layer: MASTER section 0 field structure and canonical signing material.
Description: Validates execution leases, dual governance gates, and network jail bounds.
             Provides robust ISO timestamp conversions and deterministic structures.
"""

import copy
import ipaddress
import re
from datetime import datetime, timezone
from .security import Denied, digest

GATES = (
    'it_manager_operational_necessity_signoff',
    'minotaur_labyrinth_shield_clearance_hash'
)

HEX_64_RE = re.compile(r'^[0-9a-fA-F]{64}$')

def utc(timestamp):
    return datetime.fromtimestamp(timestamp, timezone.utc).isoformat(timespec='seconds')

def timestamp(value):
    """Parses absolute UTI ISO format timestamp strings safely without brittle character slicing."""
    try:
        if not isinstance(value, str):
            raise ValueError()

        # Cleanly convert standard 'Z' suffix to formal explicit offset formatting
        normalized = value.strip()
        if normalized.endswith('Z'):
            normalized = normalized[:-1] + '+00:00'

        dt = datetime.fromisoformat(normalized)

        # Enforce that all parsed verification inputs must possess an explicit UTC offset boundary
        if dt.tzinfo is None or dt.utcoffset() is None:
            raise ValueError()

        return dt.timestamp()
    except (ValueError, TypeError, OverflowError) as exc:
        raise Denied('UTC timestamp required') from exc

def signing_material(record):
    value = copy.deepcopy(record)
    if 'agent_identity' in value and isinstance(value['agent_identity'], dict):
        value['agent_identity']['identity_assertion'] = ''
    if 'dual_governance_gates' in value and isinstance(value['dual_governance_gates'], dict):
        value['dual_governance_gates'] = {name: '' for name in GATES if name in value['dual_governance_gates']}
    return value

def assert_record(record, max_lifetime=86400, now=None):
    try:
        if not isinstance(record, dict):
            raise ValueError('Lease structure out of compliance with master protocol specifications')

        required_sections = {'lease_metadata', 'agent_identity', 'operational_bounds', 'execution_binding'}
        if not required_sections.issubset(record.keys()):
            raise ValueError('Lease structure out of compliance with master protocol specifications')

        meta, agent, bounds, binding = (record[k] for k in (
            'lease_metadata', 'agent_identity', 'operational_bounds', 'execution_binding'
        ))

        if not {'lease_id', 'timestamp_utc'}.issubset(meta.keys()):
            raise ValueError('Lease structure out of compliance with master protocol specifications')
        if not {'requesting_agent', 'commanding_authority'}.issubset(agent.keys()):
            raise ValueError('Lease structure out of compliance with master protocol specifications')
        if not {'target_endpoint', 'network_jail_ip'}.issubset(bounds.keys()):
            raise ValueError('Lease structure out of compliance with master protocol specifications')
        if not {'payload_hash', 'operation'}.issubset(binding.keys()):
            raise ValueError('Lease structure out of compliance with master protocol specifications')

        if agent.get('commanding_authority') != 'IT_AI_Manager_v15.0':
            raise ValueError('Lease structure out of compliance with master protocol specifications')

        for value in [
            meta.get('lease_id'), meta.get('nonce'), agent.get('requesting_agent'),
            bounds.get('target_endpoint'), binding.get('operation')
        ]:
            if value is not None and (not isinstance(value, str) or not value or '*' in value):
                raise ValueError('Lease structure out of compliance with master protocol specifications')

        if binding.get('payload_hash') and not HEX_64_RE.fullmatch(binding['payload_hash']):
            raise ValueError('Lease structure out of compliance with master protocol specifications')
        if binding.get('agent_public_key') and not HEX_64_RE.fullmatch(binding['agent_public_key']):
            raise ValueError('Lease structure out of compliance with master protocol specifications')

    except Exception as exc:
        if isinstance(exc, ValueError) and 'master protocol specifications' in str(exc):
            raise
        raise ValueError('Lease structure out of compliance with master protocol specifications') from exc

    # Robust IP tracking engine integration Layer verification
    try:
        if 'network_jail_ip' in bounds:
            ipaddress.ip_address(bounds['network_jail_ip'])
    except Exception as exc:
        raise ValueError('Lease structure out of compliance with master protocol specifications') from exc

core_platform/provider_connections.py.content:
"""
Module: core_platform.provider_connections
Architectural Layer: Remote Remote Online Notarization (RON) API Gateway Adapter
Description: Secure connection handlers for SignWell and BlueNotary platform endpoints.
             Enforces explicit payload boundaries, non-redirecting transport bounds,
             and robust timeout gates to prevent internal thread-locking.
"""

import json
import re
import urllib.error
import urllib.parse
import urllib.request

class ProviderConnectionError(RuntimeError):
    pass

class NoRedirect(urllib.request.HTTPRedirectHandler):
    """Fail-closed redirect fence: forces immediate halts instead of credentials forward leaking."""
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        # Never forward an API credential payload to a redirected remote host destination
        return None

class ReadOnlyProviderClient:
    """Bounded query manager enforcing absolute input validation fences over external APIs."""

    def __init__(self, provider, api_key, *, timeout=10, opener=None):
        if provider not in ('signwell', 'bluenotary'):
            raise ValueError('Unsupported provider platform allocation specified')
        if not isinstance(api_key, str) or not 8 <= len(api_key) <= 400 or any(
            ord(c) < 33 or ord(c) > 126 for c in api_key
        ):
            raise ValueError('API credential configuration out of safe boundaries')
        if not 1 <= timeout <= 30:
            raise ValueError('Timeout parameter outside allowed range matrix')

        self.provider = provider
        self._api_key = api_key
        self.timeout = timeout

        # Configure a secure non-redirecting transport pool natively
        self._opener = opener if opener is not None else urllib.request.build_opener(NoRedirect())

    def _get_auth_headers(self):
        """Constructs safe explicit authentication dictionary matrices uniformly."""
        if self.provider == 'signwell':
            return {'X-Api-Key': self._api_key}
        elif self.provider == 'bluenotary':
            return {'X-Authorization-Token': self._api_key}
        return {}

    def _get(self, url):
        headers = self._get_auth_headers()
        headers.update({
            'Accept': 'application/json',
            'User-Agent': 'Sanders Dash & Seal Platform Sync Gateway v1.0'
        })

        try:
            req = urllib.request.Request(url, headers=headers, method='GET')
            with self._opener.open(req, timeout=self.timeout) as response:
                raw_response = response.read(1024 * 1024 + 1)
                if len(raw_response) > 1024 * 1024:
                    raise ValueError('Provider transmission response size threshold exceeded')
                return json.loads(raw_response.decode('utf-8'))
        except (urllib.error.URLError, ValueError, KeyError) as error:
            raise ProviderConnectionError(f"External platform network lookup failure ({self.provider}): {str(error)}") from error

    def get_document(self, document_id):
        if self.provider != 'signwell':
            raise ProviderConnectionError('SignWell operation track only')
        safe_id = self._safe_id(document_id)
        return self._get(f'https://signwell.com{safe_id}/')

    def get_session(self, session_id):
        if self.provider != 'bluenotary':
            raise ProviderConnectionError('BlueNotary operation track only')
        safe_id = self._safe_id(session_id)
        return self._get(f'https://bluenotary.us{safe_id}')

    def _safe_id(self, value):
        if not isinstance(value, str) or not value or len(value) > 128:
            raise ValueError('Invalid resource layout identification handle')
        if not all(c.isalnum() or c in '-_' for c in value):
            raise ValueError('Invalid resource identification character matrix')
        return urllib.parse.quote(value, safe='')

class WriteProviderClient(ReadOnlyProviderClient):
    """Transaction publisher pushing validated case payloads cleanly over remote sessions."""

    def create_request(self, url, payload):
        if not isinstance(payload, dict):
            raise ValueError('Structured dictionary request layout body required')

        headers = self._get_auth_headers()
        serialized_payload = json.dumps(payload, allow_nan=False).encode('utf-8')

        headers.update({
            'Content-Type': 'application/json; charset=utf-8',
            'Content-Length': str(len(serialized_payload)),
            'Accept': 'application/json',
            'User-Agent': 'Sanders Dash & Seal Platform Sync Gateway v1.0'
        })

        try:
            req = urllib.request.Request(url, data=serialized_payload, headers=headers, method='POST')
            with self._opener.open(req, timeout=self.timeout) as response:
                raw_response = response.read(1024 * 1024 + 1)
                if len(raw_response) > 1024 * 1024:
                    raise ValueError('Provider transmission response size threshold exceeded')

                result = json.loads(raw_response.decode('utf-8'))
                if not isinstance(result, dict):
                    raise ValueError('Unexpected remote data format returned')
                return result
        except (urllib.error.URLError, ValueError, KeyError) as error:
            raise ProviderConnectionError(f"External platform push execution failure ({self.provider}): {str(error)}") from error

core_platform/provider_workflows.py.content:
"""Human-directed, case-bound provider requests; never a notarial execution grant.

Only fingerprints and provider references are persisted. An uncertain POST is
never retried automatically: neither provider documents an idempotency guarantee.
"""
import hashlib
import json
import re
import sqlite3
import time
from datetime import datetime
from .provider_connections import ProviderConnectionError


class ProviderUnavailable(Exception):
    pass


class ProviderRequestConflict(Exception):
    pass


def text(value, maximum=160):
    if (not isinstance(value, str) or not 1 <= len(value) <= maximum
            or value != value.strip() or any(ord(c) < 32 for c in value)):
        raise ValueError('Invalid provider request field')
    return value


def identifier(value):
    value = text(value, 128)
    if not re.fullmatch(r'[A-Za-z0-9_-]+', value):
        raise ValueError('Invalid provider resource identifier')
    return value


def email(value):
    value = text(value, 254)
    if not re.fullmatch(r'[^\s@]+@[^\s@]+\.[^\s@]+', value):
        raise ValueError('Invalid recipient email')
    return value


def prepare(provider, data, case_id, *, signwell_test_mode=False):
    if not isinstance(data, dict):
        raise ValueError('Request object required')
    request_id = identifier(data.get('request_id'))
    if provider == 'signwell':
        if set(data) != {'request_id', 'template_id', 'name', 'recipients'}:
            raise ValueError('Invalid SignWell fields')
        recipients = data['recipients']
        if not isinstance(recipients, list) or not 1 <= len(recipients) <= 20:
            raise ValueError('Recipients required')
        normalized = []
        for recipient in recipients:
            if not isinstance(recipient, dict) or set(recipient) != {'id', 'placeholder_name', 'name', 'email'}:
                raise ValueError('Invalid SignWell recipient')
            normalized.append({'id': identifier(recipient['id']),
                'placeholder_name': text(recipient['placeholder_name']),
                'name': text(recipient['name']), 'email': email(recipient['email'])})
        if len({r['id'] for r in normalized}) != len(normalized):
            raise ValueError('Duplicate recipient identifier')
        if len({r['placeholder_name'] for r in normalized}) != len(normalized):
            raise ValueError('Duplicate template placeholder')
        payload = {'template_id': identifier(data['template_id']), 'name': text(data['name']),
            'recipients': normalized, 'draft': False, 'test_mode': signwell_test_mode,
            'metadata': {'sds_case_id': case_id, 'sds_request_id': request_id}}
    elif provider == 'bluenotary':
        required = {'request_id', 'document_templates', 'all_signers', 'session_notary_email',
                    'notarization_timing_type'}
        if set(data) not in (required, required | {'session_timing'}):
            raise ValueError('Invalid BlueNotary fields')
        templates = data['document_templates']; signers = data['all_signers']
        if not isinstance(templates, list) or not 1 <= len(templates) <= 20:
            raise ValueError('Provider templates required')
        if not isinstance(signers, list) or not 1 <= len(signers) <= 20:
            raise ValueError('Signers required')
        normalized = []
        for signer in signers:
            if not isinstance(signer, dict) or set(signer) != {'first_name', 'last_name', 'email'}:
                raise ValueError('Invalid BlueNotary signer')
            normalized.append({'first_name': text(signer['first_name'], 50),
                'last_name': text(signer['last_name'], 50), 'email': email(signer['email'])})
        timing = data['notarization_timing_type']
        if timing not in ('notarize_now', 'notarize_later'):
            raise ValueError('Invalid session timing')
        payload = {'signing_type': 'ron', 'session_type': 'gnw',
            'notarization_id': hashlib.sha256((case_id + ':' + request_id).encode()).hexdigest(),
            'document_templates': [identifier(t) for t in templates], 'all_signers': normalized,
            'session_notary_email': email(data['session_notary_email']),
            'notarization_timing_type': timing}
        if timing == 'notarize_later':
            scheduled = text(data.get('session_timing'), 50)
            parsed = datetime.fromisoformat(scheduled.replace('Z', '+00:00'))
            if parsed.tzinfo is None or parsed.timestamp() <= time.time():
                raise ValueError('Future timezone-aware session time required')
            payload['session_timing'] = scheduled
        elif 'session_timing' in data:
            raise ValueError('Unexpected session time')
    else:
        raise ValueError('Unsupported provider')
    return request_id, payload


class ProviderWorkflows:
    def __init__(self, path, cases, operator, audit, clients, *, signwell_test_mode=False):
        self.path, self.cases, self.operator, self.audit, self.clients = str(path), cases, operator, audit, clients
        self.signwell_test_mode = signwell_test_mode
        with self.connect() as db:
            db.execute('''CREATE TABLE IF NOT EXISTS provider_requests (
                case_id TEXT NOT NULL, provider TEXT NOT NULL, request_id TEXT NOT NULL,
                actor TEXT NOT NULL, fingerprint TEXT NOT NULL, state TEXT NOT NULL,
                resource_id TEXT, created_at INTEGER NOT NULL,
                PRIMARY KEY(case_id,provider,request_id))''')

    def connect(self):
        db = sqlite3.connect(self.path, timeout=10); db.row_factory = sqlite3.Row
        return db

    def authorize(self, case_id, actor):
        if self.operator(actor) is not True:
            raise PermissionError('Operator required')
        self.cases.get(case_id)

    def records(self, case_id, actor):
        self.authorize(case_id, actor)
        with self.connect() as db:
            return [dict(row) for row in db.execute('''SELECT provider,request_id,state,resource_id
                FROM provider_requests WHERE case_id=? ORDER BY created_at DESC,rowid DESC LIMIT 100''', (case_id,))]

    def submit(self, case_id, actor, provider, data):
        self.authorize(case_id, actor)
        request_id, payload = prepare(provider, data, case_id, signwell_test_mode=self.signwell_test_mode)
        fingerprint = hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(',', ':'),
                                               allow_nan=False).encode()).hexdigest()
        client = self.clients.get(provider)
        if client is None:
            raise ProviderUnavailable(provider + '_credentials_not_configured')
        key = (case_id, provider, request_id)
        self.audit.preserve({'stage': 'HUMAN_PROVIDER_REQUEST', 'case_id': case_id,
            'provider': provider, 'request_id': request_id, 'actor': actor, 'sha256': fingerprint})
        with self.connect() as db:
            db.execute('BEGIN IMMEDIATE')
            previous = db.execute('SELECT * FROM provider_requests WHERE case_id=? AND provider=? AND request_id=?', key).fetchone()
            if previous:
                if previous['fingerprint'] != fingerprint or previous['state'] != 'CREATED':
                    raise ProviderRequestConflict('Request reused or outcome requires provider reconciliation')
                return self.receipt(previous)
            db.execute('INSERT INTO provider_requests VALUES (?,?,?,?,?,?,?,?)',
                       (*key, actor, fingerprint, 'SUBMITTING', None, int(time.time())))
        try:
            result = client.create_request(payload)
            resource = identifier(result.get('id') if provider == 'signwell' else result.get('bn_session_id'))
            if provider == 'bluenotary' and result.get('response') != 'Pass':
                raise ProviderConnectionError('Provider did not accept session')
        except Exception:
            with self.connect() as db:
                db.execute('UPDATE provider_requests SET state=? WHERE case_id=? AND provider=? AND request_id=?',
                           ('OUTCOME_UNKNOWN', *key))
            self.audit.preserve({'stage': 'PROVIDER_OUTCOME_UNKNOWN', 'case_id': case_id,
                                 'provider': provider, 'request_id': request_id})
            raise ProviderUnavailable('Provider outcome unknown; inspect provider before creating another request') from None
        with self.connect() as db:
            db.execute('UPDATE provider_requests SET state=?,resource_id=? WHERE case_id=? AND provider=? AND request_id=?',
                       ('CREATED', resource, *key))
        self.audit.preserve({'stage': 'PROVIDER_REQUEST_CREATED', 'case_id': case_id,
            'provider': provider, 'request_id': request_id, 'resource_id': resource})
        return self.receipt({'provider': provider, 'request_id': request_id, 'state': 'CREATED', 'resource_id': resource})

    @staticmethod
    def receipt(record):
        return {**{k: record[k] for k in ('provider', 'request_id', 'state', 'resource_id')},
                'notarial_act_executed': False}

core_platform/realtime_api.py.content:
"""WSGI API for realtime/video + platform status (Phase 2 linker).

Routes
------
* ``GET  /api/realtime/status``   -- provider + config status (booleans only, no secrets).
* ``POST /api/realtime/room``     -- create a LiveKit/Daily room via the injected client.
                                     503 ``not_configured`` when no provider is set up.
* ``POST /api/realtime/token``    -- mint a session-scoped LiveKit token for one room +
                                     identity. 503 when LiveKit is not configured.
* ``POST /api/realtime/signaling/validate`` -- validate one offer/answer/ICE message
                                     against the worker contract (pure validation,
                                     no relay, no peer connection).
* ``GET  /api/platform/status``   -- combined platform-services status (see
                                     ``core_platform.platform_services``).
* ``GET  /api/video/status``      -- alias of /api/realtime/status for the voice page.

Everything here fails honestly: unconfigured providers answer 503 with an
``error`` code instead of pretending a call works, and no secret value is
ever returned.  Backends are injected (fakes in tests); the deployment
default wires clients from the environment with no transport, so room
operations raise ``RealtimeNotConfigured`` / ``RealtimeUnavailable``
until a real SDK/transport is installed.
"""

from __future__ import annotations

import json
from typing import Any, Callable

from .daedalus_voice import validate_signaling_message, validate_video_session
from .livekit_realtime import (
    DailyClient,
    FakeRoomService,
    LiveKitClient,
    RealtimeConfig,
    RealtimeError,
    RealtimeNotConfigured,
    validate_identity,
    validate_room_name,
)
from .platform_services import platform_status

MAX_BODY = 65536


def _json(start: Callable, status: str, payload: dict[str, Any]) -> list[bytes]:
    body = json.dumps(payload, separators=(",", ":")).encode()
    start(status, [
        ("Content-Type", "application/json"),
        ("Content-Length", str(len(body))),
        ("Cache-Control", "no-store"),
        ("X-Content-Type-Options", "nosniff"),
    ])
    return [body]


def _read_json(environ: dict[str, Any]) -> dict[str, Any]:
    try:
        length = int(environ.get("CONTENT_LENGTH") or 0)
    except (TypeError, ValueError):
        length = 0
    if length <= 0 or length > MAX_BODY:
        raise ValueError("invalid body length")
    raw = environ["wsgi.input"].read(length)
    if len(raw) != length:
        raise ValueError("incomplete body")
    data = json.loads(raw.decode("utf-8"))
    if not isinstance(data, dict):
        raise ValueError("JSON body must be an object")
    return data


def create_realtime_app(
    *,
    livekit: LiveKitClient | None = None,
    daily: DailyClient | None = None,
    config: RealtimeConfig | None = None,
    platform_env: dict[str, str] | None = None,
) -> Callable:
    """Build the realtime/platform WSGI app with injected (possibly fake) clients."""
    livekit = livekit if livekit is not None else LiveKitClient.from_env(platform_env)
    daily = daily if daily is not None else DailyClient.from_env(platform_env)
    config = config if config is not None else RealtimeConfig.from_env(platform_env)

    def app(environ: dict[str, Any], start: Callable) -> list[bytes]:
        path = environ.get("PATH_INFO") or "/"
        method = environ.get("REQUEST_METHOD") or "GET"

        if path in ("/api/realtime/status", "/api/video/status") and method == "GET":
            return _json(start, "200 OK", {"status": "ok", **config.status()})

        if path == "/api/platform/status" and method == "GET":
            return _json(start, "200 OK", {"status": "ok", **platform_status(platform_env)})

        if path == "/api/realtime/room" and method == "POST":
            try:
                data = _read_json(environ)
                room = validate_room_name(data.get("room"))
                configured_provider = config.provider if config.provider != "none" else ""
                provider = (data.get("provider") or configured_provider or "livekit").lower()
                if provider == "livekit":
                    result = livekit.create_room(room)
                elif provider == "daily":
                    result = daily.create_room(room)
                else:
                    return _json(start, "400 Bad Request", {"status": "error", "error": "unknown_provider"})
                return _json(start, "200 OK", {"status": "ok", "provider": provider, "room": result})
            except RealtimeNotConfigured as exc:
                return _json(start, "503 Service Unavailable", {"status": "error", "error": "not_configured", "detail": str(exc)})
            except RealtimeError as exc:
                return _json(start, "503 Service Unavailable", {"status": "error", "error": "unavailable", "detail": str(exc)})
            except (ValueError, KeyError) as exc:
                return _json(start, "400 Bad Request", {"status": "error", "error": "invalid_request", "detail": str(exc)})

        if path == "/api/realtime/token" and method == "POST":
            try:
                data = _read_json(environ)
                room = validate_room_name(data.get("room"))
                identity = validate_identity(data.get("identity"))
                token = livekit.issue_token(room=room, identity=identity)
                return _json(start, "200 OK", {
                    "status": "ok",
                    "provider": "livekit",
                    "room": room,
                    "identity": identity,
                    "url": livekit.url,
                    "token": token,
                })
            except RealtimeNotConfigured as exc:
                return _json(start, "503 Service Unavailable", {"status": "error", "error": "not_configured", "detail": str(exc)})
            except (ValueError, KeyError) as exc:
                return _json(start, "400 Bad Request", {"status": "error", "error": "invalid_request", "detail": str(exc)})

        if path == "/api/realtime/signaling/validate" and method == "POST":
            try:
                data = _read_json(environ)
                session = validate_video_session(
                    session_id=data.get("session_id", ""),
                    token=data.get("token", ""),
                )
                frame = validate_signaling_message(data.get("message") or {}, session_id=session["session_id"])
                return _json(start, "200 OK", {"status": "ok", "valid": True, "frame": frame})
            except (ValueError, KeyError) as exc:
                return _json(start, "400 Bad Request", {"status": "error", "error": "invalid_request", "detail": str(exc)})

        return _json(start, "404 Not Found", {"status": "error", "error": "not_found"})

    return app


def create_realtime_app_with_fakes() -> Callable:
    """Test/local helper: app wired to a FakeRoomService (no provider, no network)."""
    fake = FakeRoomService()
    livekit = LiveKitClient(url="https://livekit.example.invalid", api_key="APfake", api_secret="secret", transport=fake)
    return create_realtime_app(livekit=livekit, daily=DailyClient(transport=fake))


def application(environ: dict[str, Any], start: Callable) -> list[bytes]:
    """Deployment default: env-wired clients, no transport (honest 503s until configured)."""
    return create_realtime_app()(environ, start)

core_platform/rtsa_assessments.py.content:
"""Sanders Dash & Seal: 14 distinct deterministic RTSA offline assessment handlers.

These are bounded, auditable functional reference implementations, not AI models.
No network, filesystem, credential, or production action is performed.
"""
from __future__ import annotations
from dataclasses import dataclass
from hashlib import sha256
import json

from core_platform.rtsa_registry import RTSA_ROLES, get_rtsa

class AssessmentRejected(ValueError):
    pass

@dataclass(frozen=True)
class Assessment:
    rtsa: str
    role: str
    outcome: str
    findings: tuple[str, ...]
    input_digest: str
    execution_allowed: bool = False

def _list(value: object, key: str) -> list:
    if not isinstance(value, list) or len(value) > 100:
        raise AssessmentRejected("INVALID_LIST:" + key)
    return value

def _assess(name: str, data: dict) -> tuple[str, ...]:
    # One distinct, deterministic assessment policy per canonical RTSA identity.
    if name == "ARCHITECT":
        required = ("components", "interfaces", "trust_boundaries")
        return tuple("MISSING_" + key.upper() for key in required if not data.get(key)) or ("ARCHITECTURE_INPUTS_PRESENT",)
    if name == "ARCHIMEDES #43":
        return ("BUILD_TESTS_MISSING",) if not data.get("tests_passed") else ("BUILD_TESTS_REPORTED_PASSING_NOT_VERIFIED",)
    if name == "PROMETHEAN":
        return ("UNREVIEWED_THREAT_CASES",) if _list(data.get("threat_cases", []), "threat_cases") else ("NO_THREAT_CASES_SUBMITTED",)
    if name == "HYDRA-Q":
        return ("CRYPTO_POLICY_UNSPECIFIED",) if not data.get("algorithm_policy") else ("CRYPTO_POLICY_REVIEW_REQUIRED",)
    if name == "LABYRINTH":
        return ("TRUST_BOUNDARY_GAPS",) if not data.get("deny_by_default") else ("ZERO_TRUST_EVIDENCE_REQUIRED",)
    if name == "CERBERUS":
        return ("EVIDENCE_CHAIN_UNVERIFIED",) if not data.get("hash_chain_verified") else ("EXTERNAL_ANCHOR_STILL_REQUIRED",)
    if name == "MINOTAUR":
        return ("SHIELD_CLEARANCE_DENIED",) if not data.get("shield_clearance") else ("INDEPENDENT_ATTESTATION_REQUIRED",)
    if name == "CHORUS":
        return ("UNBOUNDED_MODALITY",) if not data.get("approved_modalities") else ("MULTIMODAL_POLICY_REVIEW_REQUIRED",)
    if name == "COBOL Synthetic AI":
        return ("LEGACY_COMPATIBILITY_UNTESTED",) if not data.get("compatibility_tests") else ("MIGRATION_REVIEW_REQUIRED",)
    if name == "SURN":
        return ("EMERGENCY_PLAN_MISSING",) if not data.get("recovery_plan") else ("EMERGENCY_DRILL_REQUIRED",)
    if name == "JUGGERNAUT":
        return ("EXECUTION_RECEIPT_MISSING",) if not data.get("receipt_digest") else ("RECEIPT_SIGNATURE_VERIFICATION_REQUIRED",)
    if name == "Sanders Labyrinth Shield 🛡️":
        return ("ISOLATION_REQUIRED",) if data.get("threat_detected") else ("DEFENSIVE_MONITORING_REQUIRED",)
    if name == "Fraud RTSA 🚨":
        return ("FRAUD_REVIEW_REQUIRED",) if data.get("suspicious_signals") else ("NO_SIGNALS_SUBMITTED",)
    if name == "Operations RTSA 📊":
        return ("INCIDENT_TRIAGE_REQUIRED",) if data.get("active_incidents") else ("NO_INCIDENTS_SUBMITTED",)
    raise AssessmentRejected("NO_ROLE_HANDLER")

def assess(name: str, data: dict) -> Assessment:
    role = get_rtsa(name)
    if not isinstance(data, dict):
        raise AssessmentRejected("INPUT_MUST_BE_OBJECT")
    if len(data) > 100:
        raise AssessmentRejected("INPUT_TOO_LARGE")
    try:
        canonical = json.dumps(data, sort_keys=True, separators=(",", ":"), allow_nan=False)
    except (TypeError, ValueError) as exc:
        raise AssessmentRejected("INPUT_NOT_CANONICAL_JSON") from exc
    if len(canonical.encode("utf-8")) > 65536:
        raise AssessmentRejected("INPUT_TOO_LARGE")
    findings = _assess(name, data)
    return Assessment(rtsa=name, role=role.mission, outcome="ADVISORY_ONLY",
                      findings=findings, input_digest=sha256(canonical.encode()).hexdigest())

core_platform/security.py.content:
"""Sanders Dash & Seal: development implementation of bounded authority.

Trusted host library; does not execute payloads or claim OS/network isolation.
Production trust keys must be supplied by separately operated authorities.
"""
import base64
import hashlib
import json
import math
import secrets
import sqlite3
import time
from pathlib import Path
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey
from cryptography.hazmat.primitives.serialization import Encoding, PublicFormat

PLATFORM = 'Sanders Dash & Seal'
ROLES = ('IT_AI_Manager_v15.0', 'MINOTAUR')

class Denied(Exception):
    """Fail-closed authorization result."""

def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), allow_nan=False).encode()

def digest(payload):
    return hashlib.sha256(payload).hexdigest()

def public_hex(key):
    return key.public_bytes(Encoding.Raw, PublicFormat.Raw).hex()

def sign(key, domain, value):
    return base64.b64encode(key.sign(domain.encode() + b'\0' + canonical(value))).decode()

def verify(key_hex, signature, domain, value):
    try:
        Ed25519PublicKey.from_public_bytes(bytes.fromhex(key_hex)).verify(
            base64.b64decode(signature, validate=True), domain.encode() + b'\0' + canonical(value))
    except Exception as exc:
        raise Denied('Invalid cryptographic proof') from exc

class TwinGate:
    def __init__(self, trusted_keys):
        if set(trusted_keys) != set(ROLES):
            raise ValueError('Two distinct trusted authority keys are required')
        decoded = {r: bytes.fromhex(k) for r, k in trusted_keys.items()}
        for value in decoded.values():
            Ed25519PublicKey.from_public_bytes(value)
        if len(set(decoded.values())) != 2:
            raise ValueError('Two distinct trusted authority keys are required')
        self.keys = {r: value.hex() for r, value in decoded.items()}

    def validate(self, domain, body, signatures):
        for role in ROLES:
            if role not in signatures:
                raise Denied('Both authorities must approve')
            verify(self.keys[role], signatures[role], domain, body)

class PBDManifestGenerator:
    @staticmethod
    def prepare(payload, artifact, scope):
        """Prepare unsigned material. This method grants no authority."""
        return {'schema': 1, 'platform': PLATFORM, 'artifact': artifact,
                'payload_hash': digest(payload), 'scope': scope}

class PBDScriptValidationEngine:
    def __init__(self, twin_gate):
        self.gate = twin_gate

    def validate(self, payload, artifact, scope, manifest):
        expected = PBDManifestGenerator.prepare(payload, artifact, scope)
        if manifest.get('body') != expected:
            raise Denied('Manifest payload, identity, or scope mismatch')
        self.gate.validate('pbd-manifest-v1', expected, manifest.get('signatures', {}))
        return expected

class Vault:
    """Durable one-use leases on one trusted SQLite host.

    No private signing keys are held here. SQLite is not an immutable store.
    """
    def __init__(self, path, twin_gate, max_lifetime, clock=time.time):
        if not max_lifetime or any(type(v) is not int or v < 1 for v in max_lifetime.values()):
            raise ValueError('Explicit positive lease lifetime policy required')
        self.max_lifetime = dict(max_lifetime)
        self.path, self.gate, self.clock = str(path), twin_gate, clock
        with self.connect() as db:
            db.executescript('''
            CREATE TABLE IF NOT EXISTS leases (
              id TEXT PRIMARY KEY, body TEXT NOT NULL, state TEXT NOT NULL);
            ''')

    def connect(self):
        return sqlite3.connect(self.path, timeout=10, isolation_level='IMMEDIATE')

    def request(self, agent_key, scope, payload, ttl, tier, requesting_agent, artifact_hash):
        from .protocol import utc, GATES, assert_record
        if type(ttl) is not int or ttl < 1:
            raise Denied('Explicit positive lease lifetime required')
        now = self.clock()
        body = {
            'lease_metadata': {'lease_id': secrets.token_hex(32),
                'timestamp_utc': utc(now), 'expires_at_utc': utc(now + ttl),
                'nonce': secrets.token_hex(32)},
            'agent_identity': {'requesting_agent': requesting_agent,
                'agent_identity_assertion': '', 'commanding_authority': 'IT_AI_Manager_v15.0'},
            'operational_bounds': {'target_endpoint': scope['endpoint'],
                'allowed_verbs': list(scope['allowed_verbs']),
                'network_jail_ips': list(scope['network_jail_ips']), 'max_execution_limit': 1},
            'dual_governance_gates': {name: '' for name in GATES},
            'execution_binding': {'agent_public_key': agent_key, 'payload_hash': digest(payload),
                'operation': scope['operation'], 'token_class': tier, 'artifact_hash': artifact_hash}}
        assert_record(body, self.max_lifetime, now)
        return body

    def mint(self, body):
        from .protocol import assert_record, signing_material, GATES
        assert_record(body, self.max_lifetime, self.clock())
        material = signing_material(body)
        self.gate.validate('pbd-lease-v2', material,
            dict(zip(ROLES, (body['dual_governance_gates'][name] for name in GATES))))
        verify(body['execution_binding']['agent_public_key'],
               body['agent_identity']['agent_identity_assertion'], 'pbd-agent-assertion-v2', material)
        lease_id = body['lease_metadata']['lease_id']
        with self.connect() as db:
            try:
                db.execute('INSERT INTO leases VALUES (?, ?, ?)',
                           (lease_id, canonical(body).decode(), 'READY'))
            except sqlite3.IntegrityError as exc:
                raise Denied('Lease already issued') from exc
        return lease_id

    def claim(self, lease_id, scope, payload, agent_proof):
        from .protocol import assert_record, check_operation
        error = None
        with self.connect() as db:
            db.execute('BEGIN IMMEDIATE')
            row = db.execute('SELECT body, state FROM leases WHERE id=?', (lease_id,)).fetchone()
            if not row:
                raise Denied('Unknown lease')
            body, state = json.loads(row[0]), row[1]
            try:
                if state != 'READY':
                    raise Denied('Revoked or consumed lease')
                assert_record(body, self.max_lifetime, self.clock())
                check_operation(body, scope, payload)
                verify(body['execution_binding']['agent_public_key'], agent_proof,
                       'pbd-agent-proof-v2', {'lease': body, 'operation': scope})
            except Denied as exc:
                error = exc
            db.execute('UPDATE leases SET state=? WHERE id=?',
                       ('REVOKED' if error else 'CONSUMED', lease_id))
        if error:
            raise error
        return body

    def revoke(self, lease_id):
        with self.connect() as db:
            db.execute('UPDATE leases SET state=? WHERE id=?', ('REVOKED', lease_id))

    def state(self, lease_id):
        with self.connect() as db:
            row = db.execute('SELECT state FROM leases WHERE id=?', (lease_id,)).fetchone()
        return row[0] if row else None


class GlobalPBDSentinel:
    """Read-only integrity scanner. Containment requires a separate deployment adapter."""
    def __init__(self, validator):
        self.validator = validator

    def scan(self, root, scope):
        findings = []
        for path in sorted(Path(root).rglob('*')):
            if path.suffix not in ('.py', '.js', '.sh'):
                continue
            artifact = path.relative_to(root).as_posix()
            try:
                if path.is_symlink():
                    raise Denied('Symlink executable is not accepted')
                manifest = json.loads(Path(str(path) + '.pbd.json').read_text())
                self.validator.validate(path.read_bytes(), artifact, scope, manifest)
                status = 'VALID'
            except (OSError, ValueError, TypeError, Denied):
                status = 'BLOCKED'
            findings.append({'artifact': artifact, 'status': status})
        return findings

